INSERT INTO `resumenes` (`id`, `autor_id`, `autor_principal`, `titulo`, `coautores`, `adscripcion1`, `adscripcion2`, `resumen_texto`, `area_id`, `estatus`, `fecha_envio`, `fecha_ultima_modificacion`, `intento_envio`, `palabras_clave`) VALUES
(36, 73, 'Olga Lucero Illescas Sánchez', 'Synthesis and Optical and Structural Characterization of Colloidal Solutions of Silicon Nanocrystals and Zinc Oxide Quantum Dots', 'José Alberto Luna López\nKarim Monfil Leyva', 'Centro de Investigación en Dispositivos Semiconductores Benemerita Universidad Autonoma de Puebla.', '1Centro de Investigación en Dispositivos Semiconductores Benemerita Universidad Autonoma de Puebla.', 'This work describes the obtaining and synthesis of silicon nanocrystals (Si-nc) and zinc oxide quantum dots (ZnO QDs) using the colloidal method, as well as their optical and structural properties. Optical characterizations were performed using UV-Vis, PL, and Raman, while structural characterizations were done with XRD and morphological characterization with SEM.\nDue to their nanometric and semiconducting nature, these colloidal solutions exhibit very interesting photoluminescent properties in the ranges of 500 to 850 nm for Si-nc and 400 to 700 nm for ZnO QDs. Their band gap energies are approximately 3.9 to 4.1 eV for Si-nc and 2.5 to 3.7 eV for ZnO QDs. In Raman spectroscopy, the characteristic band of Si-nc is defined at 512 cm-1, and the band for ZnO QDs is approximately at 98.9, 415, 933 and 1087 cm-1. In XRD, the corresponding planes for Si-nc are well-defined at θ = 28° (111), θ = 48° (220), θ = 57° (311),θ  = 69° (400), and θ = 76.6° (311). For ZnO QDs, the following diffraction peaks are observed:θ  = 32° (100),θ  = 47° (102), θ = 57° (110), θ = 63° (103), and θ = 68° (112). Using SEM, the morphology was observed, and EDS provided the material\'s composition. All the obtained properties are very interesting for applications in photovoltaic devices, light-emitting devices, health applications, water remediation, and biomedicine, among other important and interesting applications.', 2, 'Aceptado', '2025-08-30 02:56:15', '2025-09-03 15:00:44', 1, ''),
(38, 81, 'Luis Alberto Guerrero Hernandez', 'Implementación de redes LSTM para la traducción de señas del LSM con Leap Motion basado en visión infrarroja', 'Patricia Batres Mendoza\nErick Israel Guerra Hernández,\nMaría del Pilar Beristain Colorado\nJorge Fernando Ambros Antemate', 'Facultad de Sistemas Biológicos e Innovación Tecnológica, Universidad Autónoma “Benito Juárez” de Oaxaca (UABJO), Oaxaca, México', '', 'La discapacidad auditiva afecta a millones de personas y limita sus oportunidades de comunicación e inclusión social. En México, 2.3 millones viven con algún grado de pérdida auditiva, muchas de ellas dependen del Lenguaje de Señas Mexicano (LSM) para interactuar. Ante esta necesidad, los avances en inteligencia artificial ofrecen alternativas para facilitar la comunicación entre personas sordas y oyentes.\nPara reducir esta brecha, se han aplicado modelos de aprendizaje profundo al reconocimiento del LSM, principalmente redes neuronales convolucionales (CNN) y recurrentes (RNN). Este trabajo propone un modelo para la traducción automática de dos señas del LSM (“nos vemos” y “cómo estás”), empleando un sensor de radiación infrarroja para la captura de movimientos de las manos. Para el reconocimiento se utilizó una red neuronal recurrente tipo LSTM, entrenada con 173 instancias de cada seña, alcanzando un rendimiento del 99% en pruebas preliminares.\nLos resultados evidencian la viabilidad de aplicar aprendizaje profundo y dispositivos de captura de movimiento para el reconocimiento de señas del LSM. Este proyecto representa un paso hacia el desarrollo de herramientas tecnológicas que contribuyan a disminuir la brecha de comunicación y fomentar la inclusión social de personas con discapacidad auditiva.', 4, 'Aceptado', '2025-09-06 02:07:41', '2025-09-08 01:11:15', 1, 'Lenguaje de Señas,Redes Neuronales recurrentes,sensor de radiación infrarroja,Discapacidad Auditiva'),
(39, 83, 'JOSE ALBERTO LUNA LOPEZ', 'Luminiscencia de Óxido de Grafeno con Nanoestructuras de Óxido rico en silicio', 'Gabriel Omar Mendoza Conde, Zaira Jocelyn Hernández Simón, José Álvaro David Hernández de la Luz, Haydee Patricia Martínez Hernández, Karim Monfil Leyva, Javier Flores Méndez, Erick Gastellou Hernández.', 'Centro de Investigaciones en Dispositivos Semiconductores (CIDS-ICUAP), Benemérita Universidad Autónoma de Puebla  (BUAP), Col. San Manuel, Cd. Universitaria, Av. San Claudio y 14 Sur, Edificios IC5 y IC6, Puebla, Pue., 72570, México.', 'Área de Ingeniería, Benemérita Universidad Autónoma de Puebla, Ciudad Universitaria, Puebla C.P. 72570, PUE, México.', 'En el presente trabajo se realizaron Nanoestructuras de Silicio Poroso (SiP), óxido Rico en Silicio (SRO) y Óxido de Grafeno (GO), estas Nanoestructuras fueron realizadas como heteroestructuras de PSi/GO/SRO, así como estructuras PSi/GO/SRO. Las capas de SiP fueron obtenidas por grabado electroquímico y sobre estas se depositó el GO, mediante la técnica de Spin coating. Por último, películas de SRO que contiene nanocristales de Silicio fueron depositado por la técnica de método químico mediante filamento caliente (HFCVD). Las películas de SRO fueron usadas para confinar el GO. A las estructuras obtenidas se les realizaron caracterizaciones Fotoluminiscentes (FL), a los espectros FL se les realizo un análisis comparativo para poder determinar a qué longitudes de onda corresponde cada pico de emisión. En este trabajo la función principal de estas heteroestructuras hibridas es poder modular la emisión PL. Por esta razón estas heteroestructuras nanoestructuradas son buenos candidatos para aplicar en el campo de la Optoelectrónica.', 2, 'Aceptado', '2025-09-06 03:38:20', '2025-09-10 22:37:53', 1, 'Óxido de Grafeno,SRO,SiP,HFCVD,Fotoluminiscencia'),
(41, 89, 'Sigifredo Marrujo García', 'Interferómetro Mach-Zehnder en fibra óptica para detección direccional de torsión con recubrimiento metálico', 'Cipriano Guzmán-Cano, Laura G. Martínez-Ramirez, Sigifredo Marrujo-García, Marco Bianchetti, Juan M. Sierra-Hernández Vladimir P. Minkovich, Iván Hernández-Romano', 'Universidad de Guanajuato, DICIS', 'EPM, SECIHTI', 'Se presenta un sensor de torsión vectorial en fibra óptica basado en una fibra capilar de núcleo hueco (CHCF) adelgazada y recubierta con aluminio. La estructura funciona como un interferómetro de Mach-Zehnder, donde la sección adelgazada actúa como acoplador modal y el recubrimiento metálico mejora tanto el contraste de las franjas de interferencia como la sensibilidad del dispositivo. El sensor se sometió a torsiones en ambos sentidos, desde −5.818 rad/m (antihorario) hasta +5.818 rad/m (horario). El análisis espectral mostró sensibilidades de −4.259 dB/(rad/m) y 3.487 dB/(rad/m) para torsiones levógiras y dextrógiras, respectivamente. Mediante transformada de Fourier de las señales se distinguió el sentido de la torsión, evidenciando diferencias en la amplitud de los modos de la cubierta. Los resultados confirman que el recubrimiento de aluminio aumenta significativamente la respuesta respecto a dispositivos sin recubrimiento, ofreciendo una alternativa compacta, robusta y de alta sensibilidad, con aplicaciones potenciales en monitoreo estructural, robótica y sistemas aeroespaciales.', 1, 'Aceptado', '2025-09-10 15:38:59', '2025-09-11 20:52:59', 1, 'Interferómetro Mach-Zehnder,Fibra óptica capilar hueca,Torsión,Detección de direccion,Recubrimiento metálico'),
(42, 91, 'Juan Carlos Hernández García', 'Estudio de dinámicas complejas en NLPs para su aplicación en el sensado de gases', 'Julián Moisés Estudillo Ayala\nOlivier Pottiez\nJosé David Filoteo Razo\nStephanie Guadalupe Hernandez García\nMaximino Roberto Tapia García\nJesús Pablo Lauterio Cruz\nChristian Alexis Salcedo Rodríguez\nDaniel Alejandro Ramos González', 'División de Ingenierías CIS, Universidad de Guanajuato, Carretera Salamanca-Valle de Santiago Km 3.5+1.8 Km, Comunidad de Palo Blanco, Salamanca, Gto., 36885, México', 'Investigadoras e investigadores por México SECIHTI, Av. Insurgentes Sur No. 1582, Crédito Constructor, Benito Juárez, 03940, México', 'Este trabajo presenta el estudio de las dinámicas temporales internas en NLPs producidos por un esquema numérico de un láser de fibra óptica, los cuales son capaces de generar un espectro supercontinuo eficiente para la detección de gases contaminantes. El estudio se realiza mediante la implementación de ecuaciones de propagación, y el estudio de la polarización de la luz propagante a través del programa MatLab, obteniendo una base de datos que permita analizar estadísticamente el mejor perfil temporal que eficientice el funcionamiento de un sensor de gases basado en fibras SMF-28. El perfil específico del NLPs puede generado mediante un láser en configuración de figura ocho automatizado mediante sistemas de control, permitiendo demostrar el uso de NLPs para aplicaciones prácticas, cambiando los paradigmas existentes hasta el momento sobre este tema.\nPara la validación del trabajo se empleó la técnica del mallado tridimensional de pulsos de ruido y espectros supercontinuos, así como la generación de una base de datos de la correlación de diversos gases con la señal de entrada del sistema sensor. Finalmente, una de las ventajas significativas es la de contar con un generador de perfiles temporales NLPs por medio de placas polarizadoras, lo cual permite al sensor obtener diversas regiones de caracterización logrando mejorar su sensibilidad.', 1, 'Aceptado', '2025-09-10 18:19:21', '2025-09-11 20:50:24', 1, 'Láseres de fibras ópticas,Sensores de fibra óptica,Generación de supercontinuo.'),
(43, 74, 'José Adrián Rodríguez González', 'Implementación de Modelos de Lenguaje Largo en Entornos Inmersivos de Realidad Virtual', 'Uriel Haile Hernández Belmonte', 'Universidad de Guanajuato', 'Universidad de Guanajuato', 'En años recientes, el uso de inteligencias artificiales generativas, en particular los Modelos de Lenguaje Grandes (LLM por sus siglas en inglés), se han extendido en diversos campos, como la educación, la programación y también en áreas lúdicas como los videojuegos. En este trabajo, presenta la  implementación y despliegue de un LLM para la interpretación del rol del tarotista en una experiencia de realidad virtual enfocada en la lectura de las cartas del tarot. Utilizando el LLM se busca una simulación fiel y una improvisación natural de cómo una persona realizaría una lectura de cartas. Para esto, se buscó a lo largo de 1000 modelos, de los que se extrajeron aquellos que únicamente generaran texto. Se buscó un modelo que pueda ser lo suficientemente pequeño para ser ejecutado en casi cualquier computadora. Por lo que a estos modelos se evaluó su capacidad de escribir textos de manera creativa, utilizando técnicas de procesamiento de lenguaje natural y lógica difusa. Por medio de las evaluaciones, se definió que el 30% de los modelos cumplieron parcialmente los requisitos, de los cuales el 7% logró simular la naturalidad y fluidez de un tarotista. Se demostró la viabilidad técnica de combinar LLM ligeros y entornos de realidad virtual, abriendo posibilidades en el diseño y desarrollo de entornos inmersivos, lúdicos y/o educativos.', 4, 'Aceptado', '2025-09-10 18:43:35', '2025-09-11 18:54:54', 1, 'Lógica DIfusa,Modelos de Lenguaje Largo,Procesamiento de Lenguaje Natural,Creatividad,Inteligencia Artificial'),
(44, 98, 'Irving Eduardo Balanzar Urzua', 'Sensor de torsión direccional compacto y estable, implementado con fibra óptica de núcleo hueco', 'Cipriano Guzmán-Cano, Laura G. Martínez-Ramirez, Adriana Bueno-Gasca, Iván Hernández-Romano, Vladimir P. Minkovich, Edgar Oswaldo Zamorategui-Navarrete', 'Universidad de Guanajuato, DICIS', '', 'Se presenta un sensor direccional de torsión totalmente en fibra óptica, de fácil fabricación y con baja sensibilidad a temperatura y deformación mecánica. El dispositivo se basa en una fibra capilar de núcleo hueco (CHCF) adelgazada y emplea análisis modal para detectar el sentido de giro. La estructura se obtiene mediante el empalme de fibras monomodo, multimodo y CHCF, adelgazadas en un único proceso que evita la excitación de modos indeseados. El principio de operación se asemeja a un interferómetro de Mach-Zehnder, donde el modo fundamental se propaga en el núcleo hueco y un modo de orden superior en la cubierta, generando un patrón de interferencia sensible a la torsión aplicada. Las mediciones experimentales muestran una respuesta diferenciada según el sentido del giro, con sensibilidades de −0.872 dB/(rad/m) para rotación antihoraria y 0.632 dB/(rad/m) para rotación horaria. Adicionalmente, los efectos de la deformación axial (0.0003 dB/µε) y de la temperatura (0.0005 dB/°C) son prácticamente despreciables, asegurando estabilidad en la señal. Estas características hacen del sensor una alternativa compacta y robusta para aplicaciones en monitoreo estructural, sistemas robóticos y entornos aeroespaciales.', 1, 'Aceptado', '2025-09-10 19:25:05', '2025-09-11 20:49:31', 1, 'Sensor de torsión,Fibra óptica de núcleo hueco,Sensor direccional,Interferómetro de Mach-Zehnder'),
(45, 97, 'Ingrid Michelle Gutierrez Garcia', 'Estudio de los polímeros NOA86H y NOA61 en sensores de temperatura basados en un interferómetro Mach-Zehnder', 'Edgar Oswaldo Zamorategui-Navarrete, Laura G. Martínez-Ramirez, Cipriano Guzmán-Cano, Iván Hernández-Romano, Sigifredo Marrujo-García', 'Universidad de Guanajuato, DICIS', 'Fibras ópticas y sus aplicaciones', 'Se analiza el comportamiento de dos sensores de temperatura de fibra óptica basados en un interferómetro Mach-Zehnder, (IMZ) fabricados con la técnica de desplazamiento lateral (core-offset) y recubiertos con polímeros de la familia NOA. Inicialmente, ambos dispositivos presentaron una sensibilidad de aproximadamente 30 pm/°C en aire. Tras aplicar los recubrimientos, la sensibilidad aumentó de forma significativa: −6.2 nm/°C para el sensor con NOA86H y −5.5 nm/°C para el recubierto con NOA61, lo que equivale a mejoras de 198 y 179 veces respecto a sus versiones sin recubrimiento. Este incremento se asocia a las propiedades termo-ópticas y de expansión térmica de los polímeros, siendo el coeficiente termo-óptico el efecto predominante en la respuesta. Si bien ambos materiales ofrecen resultados comparables, el NOA86H demostró un desempeño ligeramente superior, por lo que se perfila como el candidato más conveniente para aplicaciones de monitoreo de temperatura con alta sensibilidad.', 1, 'Aceptado', '2025-09-10 19:27:09', '2025-09-11 20:46:13', 1, 'Polímero NOA86H,Polímero NOA61,Sensores de temperatura,Interferómetro Mach-Zehnder'),
(46, 68, 'Omar Augusto Hernández Flores', 'MODELADO DE SECADO CONVECTIVO CON TEMPERATURA VARIABLE', 'Leticia Arley Callejas Pérez , \nCarolina Romero Salazar,\nSadoth Sandoval Torres', 'Facultad de Sistemas Biológicos e Innovación Tecnológica, Universidad Autónoma Benito Juárez de Oaxaca', '', 'Se estudia el proceso de secado convectivo en un material viscoelástico (mango Ataulfo) con temperatura del aire variable.  Para ello, se utiliza una teoría de campo efectivo para describir el material y, mediante simulaciones computacionales apoyadas por modelos matemáticos que utilizan propiedades de transporte efectivas se obtienen la cinética de secado y la temperatura de la muestra. Se realiza una comparación con datos experimentales a una temperatura base del aire constante para hallar los parámetros característicos del sistema y, con ello, se realizan dos simulaciones: la primera considera un aumento de la temperatura del aire con respecto a la temperatura base y la segunda, una disminución de la temperatura del aire con respecto a la temperatura base.', 2, 'Aceptado', '2025-09-10 22:53:48', '2025-09-11 22:12:37', 1, ''),
(48, 91, 'José Ángel Diego Chacón', 'DESARROLLO DE PROTOTIPO PARA EL CONTROL AUTOMATIZADO DE LA POLARIZACION DE LA LUZ EN FIBRAS ÓPTICAS', 'Yoed Gutiérrez Velarde\nMaximino Roberto Tapia García\nStephanie Guadalupe Hernández García\nJuan Carlos Hernández García', 'División de Ingenierías CIS, Universidad de Guanajuato, Carretera Salamanca-Valle de Santiago Km 3.5+1.8 Km, Comunidad de Palo Blanco, Salamanca, Gto., 36885, México', 'Investigadoras e investigadores por México SECIHTI, Av. Insurgentes Sur No. 1582, Crédito Constructor, Benito Juárez, 03940, México', 'En este trabajo se presenta nueva información generada sobre el desarrollo de dispositivos capaces de controlar con alta precisión el estado de polarización en fibras ópticas. Este tipo de dispositivos es de gran utilidad para eficientizar los esquemas experimentales en los laboratorios de Comunicaciones Ópticas, permitiendo además el control automatizado de láseres operando regímenes CW y pulsados. \nPara el desarrollo del trabajo se realizaron actividades de investigación sobre técnicas de control de polarización; se diseñaron prototipos en software de diseño asistido por computadora (CAD, SolidWorks e Inventor), se realizó la impresión 3D de dichos prototipos para su posterior ensamblaje y la programación necesaria para obtener zonas de interés de acuerdo con el tipo de polarización requerido.\n\nEl prototipo generado constó del diseño de tres placas retardadoras (HWR y/o QWR), las cuales se incorporaron en un montaje mecánico que proporcionó una libertad de movimiento de 360° para cada placa, utilizando fibra óptica estándar SMF-28. Esto permitió una manipulación precisa del estado de polarización aplicado a un láser en configuración en figura ocho.', 1, 'Aceptado', '2025-09-11 15:03:39', '2025-09-11 20:56:09', 1, 'Fibra ópticas,Placas retardadoras,Control de polarización'),
(49, 104, 'Jose Ramon Aviña Ortiz', 'Detección De Metano CH4 Mediante El Uso De Ondas De Radio Frecuencia', '', 'Division de Ingenierias Campus Irapuato-Salamanca, Universidad de Guanajuato', '', 'La medición de la concentración de diferentes gases es de interés en aplicaciones industriales y biomédicas. Debido a esto, se propone trabajar con estructuras resonantes fabricadas con tecnología de microcintas las cuales se diseñaron como sensores de permitividad dieléctrica. Estos dispositivos dependen de los cambios en las propiedades dieléctricas del medio por lo que pueden detectar variaciones en la concentración de los gases. Dependiendo de las propiedades dieléctricas de la muestra será la respuesta eléctrica, tal que los cambios en la respuesta se pueden relacionar con variaciones en el contenido del gas en las celdas. Las respuestas eléctricas del sensor se pueden relacionar con variaciones en el contenido del volumen del contenedor, ya que, al cambiar el volumen de gas en la celda, la permitividad dieléctrica de ese entorno cambia y provoca un cambio en la frecuencia de resonancia. En base a estos cambios de frecuencia es posible clasificar las muestras según su nivel de concentración en el contenedor, así como calcular las propiedades dieléctricas del gas a analizar. Los resultados obtenidos, muestran que el incremento en el contenido del gas en la celda provoca un claro y notable cambio en la frecuencia de resonancia con lo cual es posible identificar el contenido porcentual de la celda.', 2, 'Aceptado', '2025-09-11 16:04:30', '2025-09-11 22:12:12', 1, 'Microondas, Radio frecuencia, sensor'),
(50, 105, 'Everardo Herrera Ramirez/Andrés Vásquez Mendoza', 'Análisis de los Perfiles del haz de luz que emerge de distintos tipos de fibras ópticas', 'Julián Moisés Estudillo-Ayala, Juan Manuel Sierra-Hernández, Juan Carlos Hernández-García, Jose Roberto Reyes-Ayona y Roberto Rojas-Laguna', 'Universidad de Guanajuato', '', 'El análisis de la distribución espacial de la energía de un haz láser que emerge de una fibra óptica monomodo o múltimodo, es de suma impotrtancia en el campo de las telecomunicaciones y la optoelectrónica. La caracterización completa de un haz láser requiere la medición de propiedades, como su espectro, intensidad, perfil temporal, coherencia. Esta caracterización en general suele implicar procedimientos laboriosos y equipos de medición costosos. Este trabajo describe una metodología accesible para la caracterización experimental y comparativa de los perfiles de intensidad generados por fibras ópticas monomodo y multimodo, utilizando técnicas de procesamiento digital de imágenes.', 1, 'Aceptado', '2025-09-11 16:11:06', '2025-09-11 20:54:46', 1, 'Perfiles de haz,Laseres,Fibras opticas,Procesamiento de imágenes'),
(51, 108, 'Christian Alexis Salcedo Rodriguez', 'Estudio espectral de dispositivo óptico utilizando obleas de silicio en paralelo', 'Eloisa Gallegos Arellano\nDaniel Alejandro Ramos Gonzales\nRoberto Rojas Laguna\nJuan Carlos Hernandez Garcia\nJose Roberto Reyes Ayona\nFernando Salazar Villanueva\nJuan Manuel Sierra Hernandez', 'Departamento de Ingenieria Electronica, Division de Ingenierias, Universidad de Guanajuato', 'Departamento de Mecatronica Universidad Tecnologica de Salamanca', 'La demanda de dispositivos ópticos y optoelectrónicos en el mediano infrarrojo ha ido en incremento debido a sus múltiples aplicaciones para detección de sustancias. El silicio, al tener una buena transmitancia en distancias cortas (menores a 0.5 mm), un alto índice de refracción de alrededor de 3.42 y una amplia disponibilidad en el mercado, se presenta como una alternativa para su uso en el desarrollo de estos dispositivos. En este trabajo, se presenta un análisis espectral de un arreglo en paralelo de obleas de silicio, presentando arreglos con diferentes grosores de las obleas, en un rango de 150 a 850 µm. El arreglo óptico fue montado sobre un servomotor y rotado para generar cambios en el ángulo de incidencia de la luz, generando cambios tanto en transmitancia como en frecuencia espectral. Los resultados fueron analizados y comparados con lo obtenido de manera teórica utilizando el modelo por matrices de arreglo multicapas. La mejor respuesta, con menores pérdidas y mejor coherencia óptica, fue obtenida para el arreglo de [Si Air Si] con una distancia de cavidad óptica respectiva de [150 30 200] μm, mostrando cambios notables en el corrimiento de franjas.', 1, 'Aceptado', '2025-09-11 17:49:25', '2025-09-11 20:54:07', 1, 'FTIR,Obleas de silicio,Mediano infrarrojo,Modelado Multicapas'),
(52, 105, 'Everardo Herrera Ramírez', 'Investigación sobre la respuesta de micracavidades de aire en fibras ópticas a estímulos acústicos.', 'Julian M. Estudillo-Ayala, Juan M. Sierra-Hernandez, Juan C. Hernandez-Garcia, José D. Filoteo Razo, José R. Reyes Ayona, Roberto Rojas-Laguna.', 'Universidad de Guanajuato', '', 'En este trabajo de investigación mostramos las pruebas obtenidas a partir de  un interferometro Fabry Perot completamente de fibra óptica para la  detección de ondas sonoras,  el dispositivo fue fabricado con fibra de cristal fotónico de nucleo hueco obteniendo una cavidad de aire en el extremo de la fibra logrando  franjas de interferencia, en la investigación se muestran los resultados al estimular la  microesfera con ondas de frecuenacias en el  rango de 20Hz a 20Khz, los resultados obtenidos del estímulo al dispositivo son vistos  en una en  tiempo por medio de un osciloscopio.  El estudio es realizado pensando en  aplicaciones para personas con problemas auditivos.', 1, 'Aceptado', '2025-09-11 17:52:44', '2025-09-11 20:53:13', 1, 'Fabry Perot,Fibras ópticas,Sensor acústico,Interferometro de fibra'),
(53, 112, 'Saira Ximena Mendoza Lopez', 'Óptica y Nanotecnología: Sensores ópticos con recubrimiento de nanopartículas de ZnO.', 'Gutiérrez Gutiérrez Jaime\nVargas Treviño Marciano\nSegura Salvador Aristeo\n Gijón Cruz Alicia Silvia\nCanseco Urbieta Antonio\nMartínez Helmes Abraham\nCano Pérez José Luis', 'Facultad de Sistemas Biológicos e Innovación Tecnológica, Universidad Autónoma “Benito Juárez” de Oaxaca', 'Facultad de Ciencias Químicas,  Universidad Autónoma “Benito Juárez” de Oaxaca', 'Se utilizó fibra óptica monomodo de silicio (SMF-28 de Thorlabs), la cual fue tratada con ácido sulfúrico (H2SO4) y posteriormente con ácido clorhídrico (HCl) ambos concentrados, durante varias horas dentro de una campana extractora para remover impurezas, modificar su superficie y mejorar la adhesión de las nanopartículas de ZnO. El procedimiento consto de dos etapas; la primera el tratamiento químico de la fibra óptica, en el cual se hizo un lavado inicial con agua destilada y etanol, para después pasarla a una inmersión en ácido sulfúrico concentrado puro durante 40 minutos para remover el recubrimiento de plástico, una vez lavada se volvió a pasar por una inmersión en ácido clorhídrico concentrado puro durante 17 horas para obtener una mayor rugosidad, para finalizar la etapa con un lavado posterior con agua destilada y etanol. La segunda etapa fue el recubrimiento por inmersión con ZnO, donde el primer paso fue preparar una solución de nanopartículas de ZnO, con el 50% de etanol y 50% de agua destilada, dicha solución fue sometida a un sonificador por 5 minutos para mejorar la dispersión de las nanopartículas, para después sumergir la fibra óptica en la solución de ZnO y posteriormente sometida a tratamiento térmico en mufla a 500ºC durante 10 minutos.\nLa técnica de inmersión permitió obtener un recubrimiento de nps ZnO con un tamaño promedio de 30 nanómetros, lo cual se validó mediante microscopía de fuerza atómica', 1, 'Aceptado', '2025-09-11 19:46:07', '2025-09-11 20:57:41', 1, 'Sensores ópticos, recubrimiento de fibra óptica, biosensores.'),
(54, 93, 'Daniel Torres González', 'Evaluación de técnica de arco eléctrico para la fabricación de fibras adelgazadas mediante empalmadora comercial', 'José Ramón Aviña Ortiz, \nChristian Alexis Salcedo Rodríguez, \nDaniel Alejandro Ramos González, \nJessica Nohemí Figueroa Ramírez, \nJulián Moisés Estudillo Ayala, \nRoberto Rojas Laguna', 'Departamento de Electrónica, División de Ingenierías Campus Irapuato-Salamanca, Universidad de Guanajuato', '', 'Las fibras ópticas adelgazadas son componentes versátiles que han captado un gran interés en el campo de la fotónica. Estos dispositivos se destacan por sus múltiples aplicaciones, como la creación de interferómetros para filtrado en láseres de fibra, su función como elementos sensores de algunas variables físicas y su uso eficiente en la unión de fibras con revestimientos de diámetros distintos. Existen varias técnicas para reducir el diámetro de una fibra óptica, incluyendo el método de barrido de flama, el uso de láser CO2, microcalentadores cerámicos y la descarga de arco eléctrico. Este trabajo se centra en la evaluación detallada de esta última técnica para la fabricación de fibras adelgazadas. La implementación se llevó a cabo siguiendo la guía del manual de procedimientos de la empalmadora Fujikura FSM-100M. De esta forma, se analizaron diversas características del método de fabricación: la versatilidad y sus limitaciones en el diseño del dispositivo, la repetibilidad, la escalabilidad, el tiempo de fabricación y la fragilidad de los dispositivos resultantes. Además, para validar las capacidades de la técnica, se exploraron aplicaciones prácticas como la fabricación de sensores, interferómetros de doble adelgazamiento y el acoplamiento de fibras de distinto grosor. Finalmente, se presenta una comparativa de los resultados obtenidos contra la técnica de barrido de flama, destacando las ventajas y desventajas de cada método', 1, 'Aceptado', '2025-09-11 22:00:56', '2025-09-12 02:40:05', 1, 'Fibras adelgazadas,Arco eléctrico,Taper'),
(55, 115, 'Jafet Jared Bonequi Samano1', 'Instrumentos 3D Impresos para Ayudar en la Caracterización y Desarrollo de Sensores de Fibra Óptica.', 'Christian Perezcampos Mayoral1, Jaime Gutiérrez Gutiérrez1, Patricia Batres Mendoza1, Erick Israel Guerra Hernandez1, José Luis Cano Pérez1, Rogelio Enrique Pascual Veloz2.', 'Facultad de Sistemas Biológicos e Innovación tecnológica, Universidad Autónoma “Benito Juárez” de Oaxaca (FASBIT-UABJO), Av. Universidad S/N, Ex-Hacienda 5 Señores, C.P. 68120, Oaxaca de Juárez, México;', 'Doctorado en Biociencias, Facultad de Medicina y Cirugía; Universidad Autónoma \"Benito Juárez\" de Oaxaca, Ex Hacienda de Aguilera S/N, Calz. San Felipe del Agua, 68050 Oaxaca de Juárez, Oaxaca, México;', 'El desarrollo de sensores y láseres de fibra óptica requiere instrumentos precisos, pero los altos costos y la limitada disponibilidad comercial dificultan la investigación. Este trabajo presenta instrumentos impresos en 3D, económicos y adaptables, que optimizan la manipulación y caracterización de fibras ópticas a nanoescala. Fabricados con PETG, PLA y TPU, integran regletas de fibra de carbono, resortes y guías de aluminio. Los diseños, modelados en Fusión 360 (resolución 0.2 mm), incluyen: (1) monturas para curvatura controlada en sensores, midiendo cambios en la propagación de luz; (2) monturas para transporte seguro de empalmes, reduciendo pérdidas ópticas; y (3) un instrumento híbrido con regleta de fibra de carbono, resorte y guías de aluminio, generando curvatura uniforme en sensores fijados con cinta adhesiva. Evaluaciones espectrales y microscópicas confirmaron curvaturas reproducibles, útiles en monitoreo estructural y biomedicina. La impresión 3D redujo costos y tiempos, superando métodos tradicionales y permitiendo iteraciones rápidas. Este enfoque es escalable para laboratorios de óptica.', 1, 'Aceptado', '2025-09-12 02:20:02', '2025-09-12 14:22:51', 1, 'Fibras ópticas,Impresión 3D,Sensor de curvatura,Instrumentación óptica'),
(56, 120, 'Keren Daiane Cruz Andrade', 'Desechos de vidrio de un solo uso en Yucatán y su revalorización como material cementoso alternativo.', 'Jennifer Amandy Martínez Cruz\nEdwin Rene Hoil Canul', 'Universidad Politécnica de Tapachula', 'Secretaría de Ciencia, Humanidades, Tecnología e Innovación (Secihti)- Departamento de Física aplicada. Centro de Investigación y de Estudios Avanzados del Instituto Politécnico Nacional', 'En México, los residuos sólidos urbanos (RSU) representan un problema ligado al crecimiento demográfico. En Yucatán, la población incrementó de 1,955,577 habitantes en 2010 a 2,320,898 habitantes en 2020. Actualmente se generan 2,475 toneladas de RSU al día, de las cuales la capital, ciudad de Mérida, produce el 51%. La generación per cápita en Mérida es de 1.3 kg/hab/día y a nivel estatal de 0.9 kg/hab/día. El estado cuenta con un sitio de disposición final tipo “A” (100 ton/día) en Mérida, 10 tipo “C” (50 ton/día), en los municipios de Motul, Izamal, Umán, Valladolid, entre otros, y 39 sitios tipo “D” (10 ton/día). Los RSU se componen de un 33% de orgánicos y un 17.5% de cartón, PET y vidrio. Este último, al no ser biodegradable, ocupa grandes volúmenes en rellenos sanitarios, genera criaderos de vectores y puede provocar incendios en temporadas de secas. Este trabajo presenta una propuesta para la revalorización de los desechos de vidrio de un solo uso, mediante su molienda e incorporación en polvo, como reemplazo parcial del cemento o componente en materiales cementosos activados por álcalis, con el fin de elaborar pastas, morteros y concretos.', 2, 'Aceptado', '2025-09-12 03:56:46', '2025-09-17 15:49:41', 1, 'Vidrio,Cemento,Revalorización,Desechos'),
(57, 122, 'Emily del Rocío Zamudio Ramírez', 'Sensor de deformación basado en fibra óptica y laser microchip', 'Julian Moises Estudillo Ayala\nRoberto Rojas Laguna', 'UG, Facultad de ingeniería, Departamento de electrónica', '', 'Este trabajo desarrolla y analiza un sensor de deformación óptico basado en fibra, utilizando un sustrato de vidrio y un sistema interferométrico. Se aplicaron fuerzas controladas en una lámina de vidrio con un tornillo micrométrico, observando cómo el ángulo de deformación afecta los desplazamientos espectrales del patrón interferométrico. Con un láser pulsado y fibra monomodo generaron un espectro de supercontinuo, que se analizó con un espectrómetro. Los resultados muestran una relación lineal entre deformación y desplazamiento,\nconfirmando la precisión del sensor para medir fuerzas angulares. Futuras investigaciones considerarán factores ambientales, como la temperatura, para mejorar su confiabilidad.', 1, 'Aceptado', '2025-09-12 05:35:38', '2025-09-12 14:47:03', 1, 'Interderómetro,Fibra óptica,Sensor de deformación'),
(58, 121, 'Erick Armando López Ramírez', 'Diseño, Fabricación y Caracterización de un Interferómetro de Fabry–Perot con Soporte Impreso en 3D para Aplicaciones de Sensado Óptico', '', 'Universidad de Guanajuato, División de Ingenierías, Departamento de Ingeniería en Comunicaciones y Electrónica, Salamanca, México', '', 'En este trabajo se presenta el diseño, fabricación y caracterización de un interferómetro de Fabry–Perot (FPI) externo con un método de construcción simplificado y de bajo costo. El dispositivo fue elaborado mediante impresión 3D en PLA para el soporte de alineación y con un sistema de fijación que asegura la coaxialidad de fibras monomodo sin necesidad de micro-posicionadores costosos.\n\nEl sistema demostró ser reproducible, rápido de ensamblar (menos de 5 minutos) y capaz de generar espectros claros, lo que valida la viabilidad de este diseño para aplicaciones de sensado óptico, desplazamiento y mediciones de índice de refracción. Además, se proponen mejoras en el acabado superficial de las piezas impresas y en la estabilidad del soporte, con el fin de incrementar la precisión en futuras versiones.', 1, 'Aceptado', '2025-09-12 05:54:51', '2025-09-12 14:46:36', 1, 'Fabry-Perot,Sensores de Fibra Optica,Impresión 3D,Interferencia óptica'),
(59, 102, 'Aldahir Miranda Rueda', 'Evaluación del Impacto de Ondas Cuadradas en el Comportamiento del Chapulín del Maíz (Sphenarium Purpurascens)', 'Marciano Vargas Treviño¹, Erick Israel Guerra Hernández¹, Patricia Batres Mendoza¹, Guillermina Vivar Estudillo¹, José María Rodríguez Lelis²,  Christian Perezcampos Mayoral³,  José Luis Pérez Cano³, Jaime Gutiérrez Gutiérrez³, Abraham Martínez Helmes', 'Facultad de Contaduría y Administración UABJO', '', 'El chapulín del maíz (Sphenarium purpurascens) es una plaga agrícola que causa daños significativos en el Istmo de Tehuantepec, Oaxaca. Los métodos de control convencionales son problemáticos debido a su impacto ambiental y la resistencia que generan. Este estudio propone un método de control bioacústico no invasivo usando ondas cuadradas ultrasónicas. Estas señales, con sus transiciones abruptas, son ideales para evaluar respuestas en insectos y ofrecen una alternativa ecológica para el manejo de plagas. El experimento consistió en exponer a los chapulines a ondas cuadradas con frecuencias de 10 a 50 kHz. Se registraron tres tipos de respuestas: comportamiento acústico (sonidos propios del insecto), comportamiento motriz (movimiento, escape, agitación o parálisis) y plasticidad fenotípica cromática (cambios de color). Los datos se analizaron con espectrogramas y sonogramas para identificar respuestas específicas. Los resultados demostraron que S. purpurascens detecta y reacciona a las frecuencias ultrasónicas, especialmente en el rango de 20 a 35 kHz. Las ondas cuadradas funcionaron como un estímulo ideal para evaluar la sensibilidad acústica del insecto. Este enfoque es una alternativa sostenible a los métodos químicos, ya que no deja residuos ni genera resistencia. El estudio establece una base científica para el desarrollo de estrategias de control basadas en sonido.', 4, 'Aceptado', '2025-09-12 12:21:04', '2025-09-12 16:43:36', 1, 'Ondas, Frecuencia, Plagas'),
(61, 88, 'Mitzy Fernanda Vega De La Garza', 'Evaluación de Diversos Frameworks para el desarrollo de Aplicaciones Móviles Multiplataforma con Capacidades de Visión por Computadora', 'Regina Rodríguez Sandoval \nJosé Sebastian Pimentel Ramos\nOscar Ricardo Rosas Zavala\nUriel Haile Hernández Belmonte', 'Universidad De Guanajuato Campus Irapuato-Salamaca División de ingenierias', '', 'El desarrollo de aplicaciones móviles en la actualidad enfrenta desafíos significativos debido a la constante evolución en las tecnologías y la fragmentación de sistemas operativos, requiriendo una mayor inversión de recursos. Los frameworks multiplataforma emergen como una solución innovadora que ofrece herramientas, bibliotecas y estructuras predefinidas dando como resultado una reducción de costos, tiempo y complejidad técnica mediante la reutilización de código entre plataformas. Este artículo evalúa y compara tres frameworks del mercado actual: React Native, Flutter y Qt, analizando su capacidad técnica, limitaciones y adaptabilidad en diferentes contextos de desarrollo de software. Cada framework presenta enfoques distintos: React Native prioriza JavaScript, Flutter enfatiza control visual consistente, Qt ofrece flexibilidad de lenguajes y rendimiento robusto. La elección debe considerar requisitos específicos, experiencia del equipo y necesidades de integración. Un aspecto importante que fue considerado para el análisis de cada uno de estos frameworks es su compatibilidad con bibliotecas nativas especializadas de visión por computadora, en este caso OpenCV. Como resultado de nuestro análisis, se concluyó que el framework Qt provee un balance entre la complejidad técnica, experiencia de desarrollo y desempeño en los dispositivos móviles. Se listan las diversas razones que justifican esta decisión.', 4, 'En Revision', '2025-09-12 17:13:14', '2026-01-05 17:16:54', 1, 'React Native, Flutter,Qt, Multiplataforma, Desarrollo software'),
(62, 88, 'Mitzy Fernanda Vega De La Garza', 'Evaluación de Diversos Frameworks para el desarrollo de Aplicaciones Móviles Multiplataforma con Capacidades de Visión por Computadora', 'Regina Rodríguez Sandoval \nJosé Sebastian Pimentel Ramos\nOscar Ricardo Rosas Zavala\nUriel Haile Hernández Belmonte', 'Universidad De Guanajuato Campus Irapuato-Salamaca División de ingenierias', '', 'El desarrollo de aplicaciones móviles en la actualidad enfrenta desafíos significativos debido a la constante evolución en las tecnologías y la fragmentación de sistemas operativos, requiriendo una mayor inversión de recursos. Los frameworks multiplataforma emergen como una solución innovadora que ofrece herramientas, bibliotecas y estructuras predefinidas dando como resultado una reducción de costos, tiempo y complejidad técnica mediante la reutilización de código entre plataformas. Este artículo evalúa y compara tres frameworks del mercado actual: React Native, Flutter y Qt, analizando su capacidad técnica, limitaciones y adaptabilidad en diferentes contextos de desarrollo de software. Cada framework presenta enfoques distintos: React Native prioriza JavaScript, Flutter enfatiza control visual consistente, Qt ofrece flexibilidad de lenguajes y rendimiento robusto. La elección debe considerar requisitos específicos, experiencia del equipo y necesidades de integración. Un aspecto importante que fue considerado para el análisis de cada uno de estos frameworks es su compatibilidad con bibliotecas nativas especializadas de visión por computadora, en este caso OpenCV. Como resultado de nuestro análisis, se concluyó que el framework Qt provee un balance entre la complejidad técnica, experiencia de desarrollo y desempeño en los dispositivos móviles. Se listan las diversas razones que justifican esta decisión.', 4, 'Aceptado', '2025-09-12 17:20:12', '2025-09-13 15:15:46', 1, 'React Native,Flutter,Qt,Desarrollo software,Multiplataforma'),
(63, 125, 'Oscar Ricardo Rosas Zavala', 'Diseño de una aplicación para el manejo del estrés a través de la respiración guiada', 'Jose Sebastian Pimentel Ramos\nRegina Rodriguez Sandoval\nMitzy Fernada Vega de la Garza\nGerardo Ruvalcaba Palacios \nUriel Haile Hernández Belmonte', 'Universidad de Guanajuato Campus Irapuato Salamanca División de Ingenierías', '', 'El estrés académico (EA) es considerado un problema de salud mundial que afecta a estudiantes universitarios a lo largo de su formación académica, causado por las múltiples actividades académicas, así como la carga emocional que representan. La OMS lo considera un problema prevalente que requiere atención urgente, ya que la respuesta de estrés incluye la activación de procesos hemodinámicos, neuroendocrinos y autoinmunes mediados por la activación del sistema nervioso autónomo. La respiración diafragmática es una técnica efectiva de relajación que consiste en inspiraciones profundas, las cuales activan el sistema nervioso parasimpático, ofreciendo beneficios como un mejor manejo emocional. Este trabajo aborda esta necesidad mediante el diseño de una aplicación que brinda una guía y acceso a rutinas de respiración diafragmática con la finalidad de brindar un apoyo a los estudiantes para lograr un mejor manejo del estrés. La aplicación propuesta mide el estado de ánimo mediante visión por computadora y procesamiento de señales empleando la cámara frontal de los dispositivos, guiando la respiración con animaciones para lograr un estado de relajación.  Se aborda el proceso de diseño gráfico y de experiencia de usuario para la creación del prototipo. Se realizaron pruebas de usabilidad y de interacción con el prototipo, mostrando que la aplicación diseñada cumple con los objetivos planteados y la implementación es viable.', 4, 'Aceptado', '2025-09-12 17:20:45', '2025-09-13 14:34:26', 1, 'Visión por Computadora,UX,Respiración guiada,Manejo del estrés'),
(64, 91, 'Stephanie Guadalupe Hernández García', 'DESARROLLO DE UN SENSOR INTERFEROMETRICO TIPO SAGNAC ELABORADO DE FIBRA ÓPTICA PARA LA DETECCIÓN DE VIBRACIONES', 'Juan Carlos Hernández García\nMaximino Roberto Tapia García\nJulián Moisés Estudillo Ayala\nOlivier Pottiez\nJosé David Filoteo Razo\nJosé Roberto Reyes Ayona\nJuan Manuel Sierra Hernández\nRoberto Rojas Laguna', 'División de Ingenierías CIS, Universidad de Guanajuato, Carretera Salamanca-Valle de Santiago Km 3.5+1.8 Km, Comunidad de Palo Blanco, Salamanca, Gto., 36885, México', 'Investigadoras e investigadores por México SECIHTI, Av. Insurgentes Sur No. 1582, Crédito Constructor, Benito Juárez, 03940, México', 'El dispositivo se basa en la configuración de un interferómetro de Sagnac, elaborado con un acoplador 50/50 y un tramo de fibra mantenedora de polarización (PM), contando con un control de polarización lineal para mejorar el ajuste de sensibilidad de una manera más fina. Las ventajas de este dispositivo se centran en su configuración dependiente de polarización y en su fuente de bombeo; un láser que genera pulsos de ruido, teniendo regiones de operación con diversos perfiles temporales, permitiéndo ajustar la entrada del dispositivo para obtener diversas respuestas.\nPara el trabajo se utilizó un régimen pulsado con un ancho de 36 ns, observando que entre más estable y ancho sea el pulso de entrada, se tendrá una mejor respuesta de salida. Cabe resaltar que la caracterización del dispositivo fabricado se hizo de manera temporal, empleando un Osciloscopio InfiniiVision MSOX6004A, en el cual se grababan las señales de respuestas. Se suministro ruido en la fibra PM donde se empleó una bocina que inducia vibraciones producidas por un generador de frecuencias, El sensor es capaz de detectar frecuencias en un rango de Hz con una resolución de 1.8 Hz a 2.3 Hz, una sensibilidad de 0.02 ns/Hz y una exactitud de un rango de 98-100%.\nEste trabajo fue apoyado por la SECIHTI mediante las becas de posgrado CVU 1251089, proyectos Investigadoras e Investigadores por México no. 6969, y CF-2023-G-109.', 1, 'Aceptado', '2025-09-12 18:04:06', '2025-09-13 03:55:06', 1, 'Sensor de fibra óptica,Detección de vibraciones,Interferómetro Sagnac'),
(65, 91, 'Maximino Roberto tapia García', 'AUTOENCENDIDO DE UN LÁSER EMPLEANDO REDES NEURONALES', 'Juan Carlos Hernández García\nStephanie Guadalupe Hernández García\nJulián Moisés Estudillo Ayala\nOlivier Pottiez\nLuis A Rodríguez Morales\nJosé David Filoteo Razo\nDaniel Jauregui Vázquez\nRoberto Rojas Laguna', 'División de Ingenierías CIS, Universidad de Guanajuato, Carretera Salamanca-Valle de Santiago Km 3.5+1.8 Km, Comunidad de Palo Blanco, Salamanca, Gto., 36885, México', 'Investigadoras e investigadores por México SECIHTI, Av. Insurgentes Sur No. 1582, Crédito Constructor, Benito Juárez, 03940, México', 'El presente trabajo muestra la implementación de sistema de control basado en polarización para un láser pulsado de fibra, mediante un control con predicción por redes neuronales, permitiéndonos manipular de manera eficiente el comportamiento espectral y temporal del láser. La señal de referencia deseada es una señal pulsada, con una frecuencia de repetición de ∼950 kHz y un ancho global promedio de ∼10 ns. Para modificar el estado del sistema se manipulan las placas controladoras de polarización, lo que permite variar la transmisión del Espejo de Lazo Óptico No Lineal (Nonlinear Optical Loop Mirror) (NOLM). Las mediciones del estado actual del sistema se realizan de manera temporal y espectral mediante un osciloscopio programable Keysight MSOX6004A y un analizador de espectros ópticos Advantest Q8347.\nEl sistema utiliza una red neuronal para predecir las regiones de trabajo y eficientizar su búsqueda, utilizando mediciones que el mismo sistema de control puede recopilar. Se realizaron pruebas el desempeño del sistema de control, realizando la búsqueda de regiones de emisión pulsada, logrando un tiempo de autoencendido promedio de ∼11 segundos, demostrando que el módulo de control propuesto tiene aplicaciones en la caracterización y el estudio de sistemas láser de pulsos ultrarrápidos.\nEste trabajo fue apoyado por la SECIHTI mediante las becas de posgrado CVU 1251088, proyectos Investigadoras e Investigadores por México no. 6969, y CF-2023-G-109.', 1, 'Aceptado', '2025-09-12 18:14:41', '2025-09-13 03:53:54', 1, 'Láseres pulsados,Control y automatización,Redes neuronales'),
(67, 92, 'Sonia Santiago Sánchez', 'Determinación microbiológica en mango Ataulfo deshidratado en un colector solar indirecto', 'Carolina Romero Salazar\nZuemy Rodríguez Escamilla', 'Universidad Autónoma Benito Juárez de Oaxaca', 'Facultad de Sistemas Biológicos e Innovación Tecnológica', 'Según la Organización de las Naciones Unidas para la Alimentación y la Agricultura (FAO), aproximadamente un tercio de todos los alimentos producidos en el mundo se pierden en las etapas de producción y consumo, lo que supone una pérdida de 930 millones de toneladas de alimentos al año. Este trabajo se enfocó en la deshidratación de mango Ataulfo empleando energía solar como una solución a la sobreproducción en el Istmo de Tehuantepec, Oaxaca. \nEl objetivo de este trabajo fue la cuantificación de Unidades Formadoras de Colonias (UFC) en diluciones seriadas de muestras de mango deshidratado en un colector solar indirecto con convección natural de calor y como en un túnel de secado.\nDurante 8 horas se deshidrataron muestras de mango, con geometría de placa delgada, monitoreando la irradiancia, humedad relativa, el flujo de aire en el colector, la temperatura en la cámara de secado, el colector solar y las muestras de mango en la cámara de secado. Las muestras de mango en la charola superior de la cámara de secado alcanzaron una temperatura máxima de 69.3 °C, una masa inicial de 21.94 g y masa final de 4.79 g; la sección del colector solar más cercana al gabinete alcanzó una temperatura máxima de 77 °C. Con base a la Norma Oficial Mexicana: NOM-092,109 y 110-SSA1-1994, la carga microbiana en alimentos y su cuantificación por UFC en diluciones seriadas se rigen por el procedimiento, toma de muestra y control microbiológico en los alimentos.', 2, 'Aceptado', '2025-09-12 22:55:37', '2025-09-17 15:50:50', 1, ''),
(69, 128, 'Alejandro Orozco Ramirez', 'Sistema de medición de contenido de alcohol en vinos tintos utilizando sensores de fibra óptica adelgazada y aprendizaje automático', 'Julian Moises Estudillo Ayala\nJuan Manuel Sierra Hernandez\nJuan Carlos Hernandez Garcia\nJose Roberto Reyes Ayona\nRoberto Rojas Laguna', 'Universidad De Guanajuato', '', 'Durante las últimas décadas, el desarrollo de sensores ópticos ha representado una innovación en el campo de la optoelectrónica, brindando alternativas novedosas para comunicaciones, procesamiento y sensado. En particular, el sensado ha generado un gran interés debido a su alta sensibilidad y precisión. En este contexto, el presente trabajo propone un sistema para medir el porcentaje de alcohol en vinos tintos, lo cual podría reemplazar los análisis fisicoquímicos tradicionales, que resultan costosos y tardados. Para ello, se detallan los procedimientos de obtención de muestras, adquisición de espectros y su análisis mediante algoritmos de aprendizaje automático.', 1, 'Aceptado', '2025-09-13 03:55:27', '2025-09-15 04:32:57', 1, 'Sensores Ópticos,Aprendizaje automático,Análisis Espectral,Fibra Óptica Adelgazada');
INSERT INTO `resumenes` (`id`, `autor_id`, `autor_principal`, `titulo`, `coautores`, `adscripcion1`, `adscripcion2`, `resumen_texto`, `area_id`, `estatus`, `fecha_envio`, `fecha_ultima_modificacion`, `intento_envio`, `palabras_clave`) VALUES
(74, 134, 'JAIR ABDIEL HERNANDEZ CASTILLO', 'MEJORA E IMPLEMENTACIÓN DE UNA ESTRECHADORA DE FIBRA ÓPTICA POR MEDIO DE ARCO ELÉCTRICO.', 'Dr. Jaime Gutiérrez Gutiérrez (UABJO - FASBIT)\n Dr. Christian Perezcampos Mayoral (UABJO - FASBIT)\n Dr. José Luis Cano Pérez (UABJO - FASBIT)\n Prof. Guillermina Vivar Estudillo (UABJO - FASBIT)\n Dr. Marciano Vargas Treviño (UABJO - FASBIT)\n Dr. Patricia Batres Mendoza (UABJO - FASBIT)\n Dr. Jorge Fernando Ambros Antemate (UABJO - FASBIT)', 'Maestría', '', 'El presente trabajo muestra la mejora de una maquina estrechadora de fibra óptica usando arco eléctrico desde un enfoque económico, replicable y practico. Como sabemos hoy en día la fibra óptica se a convertido en el principal autor al momento de hablar de telecomunicaciones, sin embargo, esta misma cuenta con la característica de presentar interferencia en la luz debido al cambio del medio de propagación, es decir, alteraciones en la estructura de la fibra misma; es por ello, que ha logrado desenvolverse en una nueva área como lo es el desarrollo de sensores e interferómetros. Por lo anteriormente mencionado es claro que el uso de una estrechadora de fibra óptica es esencial en el área de investigación para facilitar y potenciar las investigaciones; de tal forma que las mejoras en el diseño y las partes de esta máquina favorece su implementación en los laboratorios dado que hemos logrado hacerla más económica y versátil. Siendo así que una estrechadora con estas características permite a los investigadores darse paso a nuevas áreas de oportunidad sin una inversión tan grande, así mismo permite el acceso para aquellos investigadores que no cuentan con la accesibilidad a ciertos componentes o a equipo especializado, además se caracteriza por ser una maquina más versátil y adaptable a distintos ambientes y espacios; finalmente es preciso mencionar que dicha maquina ha presentado buenos resultados al momento en la creación de tapers.', 1, 'Aceptado', '2025-09-15 03:20:17', '2025-09-16 17:23:11', 1, 'Fibras ópticas,Taper,Estrechadora'),
(75, 136, 'Ileen Viviana Pérez Cruz', 'Análisis de Concentración Delictiva en Entornos Urbanos a través de Ciencia de Datos.', 'Dr. Andrés Espinal Jiménez, Dr. Erick Israel Guerra Hernández, Dr. José Luis Cano Pérez, Dr. Marciano Vargas Treviño, Dr. Christian PerezCampos Mayoral, Dra. Patricia Batres Mendoza.', 'Laboratorio de Inteligencia Artificial, Robótica y Control. Facultad de Sistemas Biológicos e Innovación Tecnológica, Universidad Autónoma “Benito Juárez” de Oaxaca (FASBIT-UABJO)', 'Facultad de Sistemas Biológicos e Innovación Tecnológica, Universidad Autónoma “Benito Juárez” de Oaxaca (FASBIT-UABJO)', 'La delincuencia urbana constituye un reto constante para la seguridad pública, ya que no se distribuye de manera aleatoria, sino que tiende a concentrarse en determinados lugares y momentos, generando lo que se conoce como puntos calientes o hotspots. El presente trabajo analiza la criminalidad en la ciudad de Chicago durante el periodo 2022–2024, utilizando una base de datos abierta con 92,742 registros. La metodología se estructuró bajo un enfoque de ciencia de datos, que incluyó depuración de registros, estandarización de variables temporales y espaciales, análisis exploratorio de datos y visualización mediante mapas de calor y gráficas temporales.\nLos resultados muestran que los delitos contra la propiedad, como el robo (theft), presentan una incidencia elevada y persistente, mientras que otros, como el incendio intencional (arson), son esporádicos y dispersos. Asimismo, se identificaron variaciones mensuales y diferencias en la tipología dominante entre distritos. Estos hallazgos aportan evidencia útil para orientar políticas públicas, mejorar la distribución estratégica de patrullajes y avanzar hacia la integración de modelos predictivos que fortalezcan la prevención del delito.', 4, 'Aceptado', '2025-09-17 16:51:19', '2025-09-18 14:43:51', 1, 'Hotspots, criminalidad urbana, ciencia de datos, prevención del delito, análisis espacio–temporal.'),
(76, 118, 'Leticia Arely Callejas Pérez', 'SISTEMA DE SECADO SOLAR AUTOMATIZADO', 'Carolina Romero Salazar\nOmar Augusto Hernandez Florez', 'Facultad de Sistemas Biológicos e Innovación Tecnológica, UABJO', '', 'Se plantea el diseño, desarrollo e implementación de un sistema automatizado para la medición de la temperatura y la humedad relativa dentro de un secador solar directo. Paralelamente, se monitoriza la radiación solar y, en función de esta, se controla el flujo de aire que entra en el secador. Si la radiación es superior a 700 W/m², se utiliza la convección natural; si es inferior a 700 W/m², se utiliza la convección forzada por intervalos de tiempo. El sistema está compuesto por un módulo de hardware, el microcontrolador ESP32, que se encarga del control del flujo y de la adquisición de las variables físicas de temperatura y humedad, así como del almacenamiento de los datos del proceso. El sistema se alimentará con un panel solar para poder brindar una alternativa apropiada, transportable, versátil y sostenible.', 2, 'Aceptado', '2025-09-17 18:05:59', '2025-09-17 23:04:09', 1, ''),
(77, 137, 'Miriam Abigail Sánchez Medina', 'INTERPRETACIÓN VISUAL DE CLASIFICADORES DE PARÁLISIS FACIAL UTILIZANDO GRAD-CAM', 'ANDRÉS ESPINAL JIMÉNEZ, PATRICIA BATRES MENDOZA, ERICK ISRAEL GUERRA-HERNÁNDEZ4, MARCO AURELIO SOTO FIGUEROA, GUILLERMINA VIVAR-ESTUDILLO, RITA AIDE ROBLES CASTILLEJOS', 'Laboratorio de Inteligencia Artificial, Robótica y Control. Facultad de Sistemas Biológicos e Innovación Tecnológica, Universidad Autónoma “Benito Juárez” de Oaxaca (FASBIT-UABJO)', 'Division de Ciencias Economico Administrativas - Universidad de Guanajuato', 'El uso de inteligencia artificial en el ámbito médico ha crecido notablemente, pero también ha generado inquietudes respecto a la falta de transparencia en sus decisiones. Para atender esta necesidad, han surgido técnicas de inteligencia artificial interpretativa, como Grad-CAM, que permite visualizar las regiones de una imagen que influyen en la predicción de un modelo.\nEn este estudio se desarrollaron clasificadores de parálisis facial mediante tres arquitecturas de redes neuronales convolucionales. Posteriormente, se aplicó Grad-CAM para interpretar visualmente las predicciones, identificando las zonas del rostro que motivaron la clasificación. Esto permitió verificar si dichas áreas eran coherentes con los signos clínicos de la afección.\nPara la creación de los clasificadores se emplearon dos enfoques principales: transfer learning y fine-tuning. En la primera etapa, se desarrolló un clasificador binario mediante transfer learning, el cual identificó la presencia o ausencia de parálisis facial. Posteriormente, se implementó fine-tuning en dos modelos adicionales: el primero, un clasificador binario orientado a evaluar la severidad de la parálisis, distinguiendo entre casos leves y graves; y el segundo, un clasificador multi-etiqueta que determina tanto la zona afectada del rostro como el grado de severidad de la condición. Este proyecto contribuye al desarrollo de sistemas de diagnóstico médico más confiables, interpretables y transparentes.', 4, 'Aceptado', '2025-09-17 19:35:10', '2025-09-18 17:35:53', 1, 'Grad-CAM, parálisis facial, transfer learning, fine tuning.'),
(78, 126, 'Venancio Pérez Ortiz', 'DESARROLLO DEL PROTOTIPO DE SOFTWARE ORIENTADO AL FORTALECIMIENTO DEL APRENDIZAJE DE LA LENGUA CHATINA', '', 'Facultad de Sistemas Biológicos e Innovación tecnológica, Universidad Autónoma “Benito Juárez” de Oaxaca (FASBIT-UABJO)', '', 'Las lenguas originarias de México constituyen un tesoro invaluable como diversidad cultural y lingüística con cerca de 7 millones de hablantes. Oaxaca es uno de los estados con mayor diversidad lingüística con 176 variantes de 15 lenguas nacionales. En los últimos años se ha visto una disminución significativa de los hablantes de las lenguas originarias, entre ellas el Chatino. \nCon el objetivo de contribuir con la conservación de esta lengua, el presente trabajo propone un desarrollo de prototipo funcional de apoyo para la enseñanza-aprendizaje del Chatino usando la metodología Extreme Programming (XP). \nDe esta investigación resultaron cinco productos entre ellos el corpus lingüístico multimodal y de referencia preliminar, cuatro juegos didácticos ad hoc para estudiantes de nivel bachillerato. Este prototipo constituye un recurso didáctico que puede incorporarse en procesos educativos comunitarios, al mismo tiempo que abre la posibilidad de utilizar sus resultados como base para futuras investigaciones en el ámbito del procesamiento de lenguaje natural y la preservación de lenguas indígenas.', 4, 'Rechazado', '2025-09-23 01:11:34', '2025-09-26 01:12:00', 1, 'Chatino,enseñanza-aprendizaje,Software Educativo'),
(79, 149, 'José Roberto Reyes Ayona', 'Caracterización de las propiedades dieléctricas de materiales por medio de microondas', 'José Ramon Aviña Ortiz1, Juan Manuel Sierra Hernández1, Edgar Reyes Ayona2, Roberto Rojas Laguna1', 'Universidad de Guanajuato', 'UPIIG IPN', 'Se presentan técnicas de caracterización de materiales usando microondas. El análisis de materiales por medio de microondas presenta la ventaja de ser un método no invasivo, confiable y aplicable en la mayoría de los materiales sin importar que estén en el estado sólido, liquido, o gaseoso. Las técnicas presentadas se basan en 1) resonancias aisladas con énfasis en cambios de frecuencia de resonancia las cuales son útiles para identificar materiales sólidos y líquidos de mediana permitividad, 2) peine de resonancias con énfasis en cambios de las amplitudes de las resonancias las cuales son útiles para identificar diversos materiales con valores de permitividad muy bajos o altos como gases y agua, y 3) cambios en los anchos de las resonancias las cuales son útiles para describir propiedades químicas de materiales como contenido de sal o porcentaje de proteína en el material. Se presentan las principales características de los sensores usados, así como de las técnicas de extracción de los parámetros indicadores.', 2, 'Aceptado', '2025-09-23 15:54:24', '2025-09-26 18:17:00', 1, ''),
(80, 155, 'RIta Aide Robles Castillejos', 'Reconocimiento de patrones de agarre mediante imaginación motora y señales EEG para el control de prótesis de mano', 'ERICK ISRAEL GUERRA-HERNÁNDEZ1\nPATRICIA BATRES-MENDOZA1\nANDRÉS ESPINAL-JIMENEZ2\nJAIME GUTIERREZ-GUTIERREZ1\nJOSÉ GUADALUPE BELTRÁN-HERNÁNDEZ1\nMIRIAM ABIGAIL SANCHEZ-MEDINA1', 'Laboratorio de Inteligencia artificial, Robótica y control, Facultad de Sistemas Biológicos e Innovación tecnológica, Universidad Autónoma “Benito Juárez” de Oaxaca (FASBIT-UABJO)', 'División de Ciencias Económico-Administrativas- Universidad de Guanajuato', 'Las interfaces cerebro-computadora (BCI) han avanzado notablemente, especialmente en aplicaciones de rehabilitación y asistencia para personas con discapacidades motoras. La clasificación de agarres a partir de señales de EEG durante la imaginación motora es crucial para desarrollar sistemas de control de prótesis de mano. Estos sistemas no invasivos permiten un control más preciso y personalizado, lo que mejora la calidad de vida de los usuarios. Este trabajo tiene como objetivo diseñar y evaluar un modelo de clasificación capaz de distinguir entre el estado de reposo y cuatro tipos de agarre de la mano derecha: esférico, cilíndrico, de gancho y de pinza. Para este propósito, se utilizó una red neuronal de tipo LSTM. El estudio incluyó a 15 participantes, de quienes se adquirieron las señales de EEG mediante una interfaz cerebro-computadora equipada con 14 electrodos. Para optimizar el rendimiento del modelo, el conjunto de datos se dividió en proporciones del 70% para entrenamiento, 15% para validación y 15% para prueba, asegurando una distribución equilibrada de las clases. Se utilizaron 12 características extraídas de las señales EEG, previamente filtradas mediante análisis de componentes independientes (ICA) y normalizadas antes de su introducción en la red. Los resultados obtenidos en la fase de validación alcanzaron una precisión del 89.72 %, demostrando la eficacia del modelo LSTM para identificar patrones complejos de actividad cerebral.', 4, 'Aceptado', '2025-09-24 06:33:46', '2025-12-22 01:36:56', 1, 'BCI,EEG,Redes Neuronales LSTM,Patrones de Agarre,Análisis de Componentes Independientes (ICA)'),
(81, 124, 'JOSE ALBERTO CORNELIO FELICIANO', 'Procesamiento de imágenes para la identificación y análisis automático de huevecillos de Aedes aegypti', 'XIMENA GABARRÓN ANALCO, ANTONIO MARGARITO ALCÁNTARA GARCÍA, JOSÉ EDGAR LARA RAMÍREZ, MARIA DE JESUS ESTUDILLO AYALA.', 'Facultad de Sistemas Biológicos e Innovación tecnológica, Universidad Autónoma “Benito Juárez” de Oaxaca (FASBIT-UABJO)', 'Facultad de Ciencias, Universidad Nacional Autónoma de México; Departamento de Prevención y Control de Enfermedades Transmitidas por Vector, Servicios de Salud de Oaxaca.', 'El monitoreo de las poblaciones del mosquito Aedes aegypti, vector de dengue, zika y chikungunya, representa un desafío prioritario para la salud pública, ya que los métodos convencionales de identificación y cuantificación de huevecillos son manuales, laboriosos y susceptibles a errores humanos, lo que limita la rapidez y confiabilidad de la vigilancia entomológica. En este trabajo se propone un enfoque automatizado basado en técnicas de procesamiento de imágenes para la detección y caracterización de huevecillos de Aedes aegyptiy. La metodología está formada por cuatro etapas:  adquisición de imágenes microscópicas, preprocesamiento para mejorar la calidad visual, detección de objetos mediante algoritmos de segmentación y, análisis morfométrico para la clasificación y filtrado de características. Los resultados evidencian una reducción significativa en el tiempo de cuantificación y demuestran la viabilidad de esta alternativa para el monitoreo del vector, así como su capacidad para clasificar huevecillos, confirmando que el procesamiento de imágenes puede superar las limitaciones de los métodos manuales.', 4, 'Aceptado', '2025-09-24 15:23:44', '2025-09-26 01:13:49', 1, 'Procesamiento de imágenes,Aedes aegypti,Análisis morfométrico'),
(82, 157, 'Anayansi Jimenez Rodriguez', 'Sensor óptico de temperatura: interferometro Mach - Zehnder con estructura tipo cacahuate en el rango visible', 'Jaime Gutierrez Gutierrez ,Christian Perezcampos Mayoral, Marciano Vargas Treviño, Erick Israel Guerra Hernandez, Jose Luis Cano Perez', 'Facultad de Sistemas Biologicos e innovacion tecnologica', '', 'Se propone un sensor de temperatura basado en una estructura tipo “cacahuate”, conformada por fibra monomodo (SMF) y fibra dopada con erbio (EDF) en configuración SMF-EDF-SMF, que funciona como un interferómetro de Mach–Zehnder (MZI) en el rango de luz visible. La estructura fue fabricada mediante descargas de arco eléctrico, obteniendo diámetros cónicos de 147.41 µm y 152.77 µm, con una separación de 3 cm correspondiente al segmento de EDF (Er 80-8/125). El sensor fue caracterizado en un rango de 30 °C a 280 °C, alcanzando sensibilidades de 1.412 dBm·m⁻¹ con una R² = 0.93745 y 2.696 dBm·m⁻¹ con una R² = 0.9899. Los resultados demuestran la viabilidad de la estructura propuesta para aplicaciones de sensado de temperatura en el rango visible.', 1, 'Aceptado', '2025-09-24 21:32:02', '2025-09-25 19:58:34', 1, ''),
(83, 143, 'Rodríguez Zárate Hanya Danna', 'Síntesis y caracterización de nanopartículas de SiO2  para aplicaciones hidrofóbicas.', 'Velázquez Cueto Rosa Maria, Merino Villalobos Juan Pablo, Diaz Santiago Ivonne Arisbeth, Canseco Urbieta Antonio', '1Instituto de Farmacobiología, Universidad de la Cañada, Carretera Teotitlan – San Antonio Nanahuatipan Km 1.7 s/n. Paraje Titlacuatitla, Teotitlan de Flores Magón, Oaxaca, México, C.P. 68540', 'Facultad de Ciencias Químicas,  Universidad Autónoma “Benito Juárez” de Oaxaca, Av. Universidad S/N, Ex-Hacienda 5 Señores,  68120 Oaxaca de Juárez, México.', 'La nanotecnología permite la síntesis de materiales para la fabricación de dispositivos tecnológicos a escala nanométrica (1nm-100nm). Estos materiales son de interés por sus nuevas características y propiedades. Las nanopartículas (NPs) de dióxido de silicio (SiO2) han demostrado una gran contribución en distintas áreas por las propiedades hidrofóbicas que pueden adquirir al funcionalizarse.\nEn esta investigación se dividió en cuatro etapas; en la primera fase, el silicato de sodio se diluyó en 15 mL de agua destilada y se tituló con ácido clorhídrico a 2M hasta obtener un pH neutro. La segunda fase fue la funcionalización de las NPs de SiO2 con ácido esteárico (AE). Para esto, la muestra obtenida en la primera fase fue tratada con una solución de AE en etanol al 0.05 M a 60 °C y agitación constante durante 2 horas. En la tercera fase se llevo acabo la caracterización de la muestra funcionalizada de NPs de SiO2 por espectroscopia UV-Vis y microscopia de fuerza atomica (AFM). En el UV-Vis se obtuvo un valor de absorbancia de 265 nm y en AFM NPs con una altura máxima de 2.26 nm y un diámetro máximo de 57.25 nm.En la cuarta fase, fue la comprobación de hidrofobicidad. Para esto, el papel filtro utilizado fue sometido a inmersión en la solución de las nanopartículas funcionalizadas. Ya seco el papel filtro fueron colocadas gotas de agua en la superficie. La observación de gotas coasi esféricas confirmó el carácter hidrofóbico exitosamente.', 2, 'Aceptado', '2025-09-24 23:06:27', '2025-09-26 18:15:52', 1, ''),
(84, 139, 'Joshua Amador León', 'Cinemática de un Robot Antropomórfico con Base Móvil', 'Enrique López Pérez\nPaul Ulises Osorio Castillo\nRodrigo Eduardo Méndez Hernández\nMiguel Ángel San Pablo Juárez', 'Universidad Interamericana', '', 'En este trabajo se presenta el diseño de un sistema brazo robótico antropomórfico con una base móvil de orugas compactas, impreso en 3D y usando servomotores convencionales. Adicionalmente al sistema construido, se presenta el análisis cinemático del sistema brazo-oruga móvil para aplicaciones posteriores de control. Para el caso de la base, se presenta un diseño que usa orugas laterales con rodillos de soporte para el desplazamiento. El brazo cuenta 3 grados de libertad y usa articulaciones que permiten un movimiento rotacional. El sistema de orugas permite al robot desplazarse sobre superficies planas e irregulares mientras que el brazo antropomórfico está diseñado para realizar tareas de manipulación, como sujetar, levantar o mover objetos mediante su garra final. Este robot combina movilidad y capacidad de manipulación, lo que lo convierte en una herramienta útil en aplicaciones industriales, educativas y de investigación.', 4, 'Aceptado', '2025-09-24 23:28:03', '2025-09-26 01:12:49', 1, 'Robot antropomórfico,Base móvil,Cinemática directa,Sistema mecatrónico'),
(85, 141, 'Vanessa Ivonne López Melchor', 'Diseño y Construcción de un Robot Autónomo para la Recolección de Residuos en Entornos Costeros', 'Alejandro Roberto Ramírez Jarquín \nManuel Alfredo Mariano Zorrosa \nXimena Denisse Pinelo Ramírez \nAlondra Mendoza Pablo\nDanna Lisseth Martínez Monterrubio\nDr. José Luis Cano Pérez \nDr. Christian PerezCampos Mayoral\nDra. Patricia Batres Mendoza\nDr. Marciano Vargas Treviño\nLic. Pedro Edgar García Davila\nDr. Erick Israel Guerra Hernández', 'Facultad de Sistemas Biológicos e Innovación Tecnológica', '', 'Se presenta el diseño y construcción de un robot autónomo limpiador de playas, desarrollado para el Torneo Mexicano de Robótica 2025. El robot es capaz de reconocer basura (latas negras) y distinguirla de obstáculos blancos (sombrilla, camastros y maniquí), además de identificar un contenedor rojo para depositar los residuos. La estructura fue fabricada en madera y trovicel, e integra tres sensores ultrasónicos y un sensor de color para la navegación y evasión de obstáculos. Asimismo, incorpora una cámara web con algoritmos de procesamiento de imágenes para la localización y recolección autónoma de desechos. El sistema cuenta con un brazo robótico de cuatro grados de libertad equipado con una garra fabricada mediante impresión 3D para manipular los objetos, mientras que la locomoción se basa en cuatro llantas, de las cuales las traseras son impulsadas por dos motores de 6V controlados mediante un puente H. El control general se implementó con una Raspberry Pi 4 y un Arduino UNO.\n\nEste proyecto no solo evidencia el potencial de la robótica en el ámbito ambiental, sino que también sienta las bases para futuras mejoras y aplicaciones en la limpieza de playas. Con ajustes y refinamientos en su diseño, el robot podrá desempeñar un papel más eficiente en la conservación del ecosistema costero, promoviendo el uso de la tecnología con un enfoque sostenible.\n\nEl prototipo fue distinguido con el Premio al Robot Más Innovador en la competencia.', 4, 'Aceptado', '2025-09-25 06:06:25', '2025-09-26 01:15:15', 1, 'Robot Autónomo,Procesamiento de imágenes,Brazo robótico,Limpieza de playas,Robótica ambiental'),
(86, 139, 'Ángel Arnulfo Montes López', 'Brazo manipulador de 3 grados de libertad impreso en 3D para aplicaciones de recolección de objetos resbalosos.', 'Enrique López Pérez\nLuis Enrique Hernández Gómez\nErich Diego Sánchez Kast\nMarco Antonio Vega Benitez\nGabriel Rosales Rivera\nMiguel Ángel San Pablo Juárez', 'Universidad Interamericana', '', 'En este trabajo se presenta el diseño de un brazo manipulador de 3 grados de libertad, construido en impresión 3D con PLA para aplicaciones en la enseñanza de la automatización, gracias a su programación estandarizada y su control digital a través de un protocolo serial. La implementación utiliza 3 eslabones y una pinza, acoplados mediante servomotores típicos de PWM, y sujetados por medio de tornillería estándar. Se presenta el diseño CAD hecho con Solid Works además de su manufactura hecha en Ultimaker Cura, finalmente se presenta el diseño de modelo dinámico para movimiento por medio de Euler-Lagrange. Este trabajo puede ser aplicado en acciones de recolección de residuos como basura en ríos sólo con modificar la base y agregando un grado de libertad al sistema, ya que se ha modelado e implementado una pinza de cuatro barras como efector final. Adicionalmente la construcción de este prototipo es apto para las aplicaciones de bajo presupuesto.', 4, 'Aceptado', '2025-09-25 23:47:08', '2025-09-26 01:14:57', 1, 'Brazo robot,Manipulador,Impresión 3D'),
(88, 139, 'Cristian Muñoz Aguero', 'Diseño y construcción de un sistema mecatrónico de 2 eslabones y una base móvil rotativa para la manipulación de una pinza con aplicaciones en manipulación de sustancias químicas', 'Enrique López Pérez\nHansel Antonio Martínez Flores\nEder González Hernández\nYibran Mejía Ramírez\nMiguel Ángel San Pablo Juárez', 'Universidad Interamericana', '', 'El presente proyecto se centra en el diseño, modelado e implementación de un sistema mecatrónico de 2 eslabones con una base móvil rotativa de 3 grados de libertad (GDL), concebido como una herramienta didáctica y de aplicación práctica en el ámbito de la mezcla de sustancias químicas. El sistema está conformado por una base giratoria que proporciona el movimiento de rotación, un brazo principal que permite los desplazamientos verticales, y un antebrazo articulado que incrementa el rango de alcance. En su extremo, el robot incorpora un efector final tipo pinza mecánica, el cual le brinda la capacidad de sujetar y manipular objetos de forma controlada con trayectorias predefinidas para mezcla y agitación de sustancias químicas. La construcción del prototipo está basada en un diseño modular elaborado en software CAD, lo que facilitará su manufactura, ensamblaje y posterior modificación. El sistema se controlará mediante 5 servomotores estándar controlador por PWM. Finalmente se presenta la cinemática y dinámica por medio de las ecuaciones de Euler-Lagrange y algunas simulaciones de posición cartesiana del efector final.', 4, 'Aceptado', '2025-09-26 00:36:20', '2025-09-27 17:55:13', 1, 'Sistema mecatrónico,Agitación química,Dinámica de Lagrange'),
(91, 126, 'Venancio Pérez Ortiz', 'DESARROLLO DEL PROTOTIPO DE SOFTWARE ORIENTADO AL FORTALECIMIENTO DEL APRENDIZAJE DE LA LENGUA CHATINA', 'JOSÉ GUADALUPE BELTRÁN HERNÁNDEZ\nMARIA DEL PILAR BERISTAIN COLORADO\nMARIA DE JESUS ESTUDILLO AYALA\nGUILLERMINA VIVAR ESTUDILLO', 'Facultad de Sistemas Biológicos e Innovación tecnológica, Universidad Autónoma “Benito Juárez” de Oaxaca (FASBIT-UABJO)', '', 'Las lenguas originarias de México constituyen un tesoro invaluable como diversidad cultural y lingüística con cerca de 7 millones de hablantes. Oaxaca es uno de los estados con mayor diversidad lingüística con 176 variantes de 15 lenguas nacionales. En los últimos años se ha visto una disminución significativa de los hablantes de las lenguas originarias, entre ellas el Chatino. \nCon el objetivo de contribuir con la conservación de esta lengua, el presente trabajo propone un desarrollo de prototipo funcional de apoyo para la enseñanza-aprendizaje del Chatino usando la metodología Extreme Programming (XP). \nDe esta investigación resultaron cinco productos entre ellos el corpus lingüístico multimodal y de referencia preliminar, cuatro juegos didácticos ad hoc para estudiantes de nivel bachillerato. Este prototipo constituye un recurso didáctico que puede incorporarse en procesos educativos comunitarios, al mismo tiempo que abre la posibilidad de utilizar sus resultados como base para futuras investigaciones en el ámbito del procesamiento de lenguaje natural y la preservación de lenguas indígenas.', 4, 'Aceptado', '2025-09-26 16:52:45', '2025-09-27 17:52:56', 1, 'Chatino,enseñanza-aprendizaje,Software Educativo'),
(92, 159, 'María Concepción Aguilar Martínez', 'Uso de la inteligencia artificial como método de estudio en estudiantes de primer año de medicina, del estado de Oaxaca', 'Daniela Antonio Arrazola\nBianni Concepción Arcega López \nGarcía Morales Eduardo\nDr. Uriel Eliut Ramírez Ramírez \nMtra. Luz María Quirino Vela', 'Benemérita universidad de Oaxaca', 'Benemérita Universidad de Oaxaca', 'Introducción: La inteligencia artificial es la herramienta que permite a las computadoras simular el aprendizaje humano y la resolución de problemas; en la actualidad es considerablemente usada en el nivel educativo. Objetivo: evaluar el impacto del uso de herramientas de inteligencia artificial en el proceso de estudio y resolución de tareas en estudiantes de primer año de medicina. Materiales y métodos:  se realizo un estudio descriptivo, transversal, con una muestra  conformada por 60 estudiantes de 18 a 22 años, inscritos en primer semestre de la universidad Benemérita Universidad de Oaxaca y Universidad Regional del Sureste, quienes aceptaron participar en esta investigación y se aplico un cuestionario para conocer la frecuencia, el tiempo y las actividades que realizan con la inteligencia artificial, los datos obtenidos se analizaron con estadística descriptiva con el programa estadístico SPSS 26. Resultados: la muestra estuvo conformada por 60 estudiantes, de acuerdo con nuestros resultados encontramos que dentro de nuestra población: el 94.1% utiliza inteligencia artificial para la resolución de tareas e investigación, el 5.9% no utilizan, el 40% utiliza chatGPT, el 33% utiliza META AI, el 56.9% la utiliza de 2 a 3 días por semana y el 32.7% la utiliza 3 horas al día. Conclusión: se encontró que los estudiantes de medicina suelen utilizar inteligencia artificial para realizar tareas y prepararse para evaluaciones académicas.', 4, 'Aceptado', '2025-09-26 23:16:19', '2025-09-27 17:54:20', 1, 'Inteligencia artificial,Universitarios,Medicina,Educación privada,Investigación'),
(93, 199, 'ZÓSIMO ISMAEL BAUTISTA BAUTISTA', 'DISEÑO E IMPLEMENTACIÓN DE UN PROTOTIPO FOTOVOLTAICO DE SEGUIMIENTO SOLAR', 'ROGELIO CRUZ GARCIA\nRICARDO NAVARRO SOTO', 'ESIME ZAZATENCO IPN', 'ESIME ZACATENCO IPN', 'En este trabajo se diseñó e implementó un prototipo con una instalación de paneles fotovoltaicos de un seguidor solar giratorio de un grado de libertad y una instalación de un sistema fotovoltaico de paneles fijos. Se excluyeron los inversores de corriente directa y los sistemas de almacenamientos en dichos sistemas y se obtuvieron los resultados de potencia promedio en ambos sistemas, se realizó la comparación y se estableció una mayor eficiencia en la generación de energía fotovoltaica del seguidor solar en comparación con el sistema fotovoltaico de paneles fijos. El diseño de la estructura del prototipo y los planos de acotaciones se generaron con la ayuda de un software profesional de diseño asistido por computadora para modelación de piezas y ensamblajes en 3D. Se implementaron distintos componentes electrónicos para lograr la automatización del sistema de seguimiento solar, la función de cada componente fue conectado a una placa programada tipo Arduino la cual permite desarrollar elementos autónomos mediante una programación establecida.', 4, 'Aceptado', '2025-09-27 17:42:08', '2025-09-28 16:56:41', 1, 'Prototipo, Seguidor solar, Panel fotovoltaico, Programación, Arduino'),
(94, 181, 'Daniela Antonio Arrazola', 'Riesgo cardiometabólico en adultos mexicanos', 'Biaani Concepción Arcega López \nMaría Concepción Aguilar Martínez \nEduardo García Morales\nLuz María Quirino Vela', 'Benemérita Universidad de Oaxaca', '', 'Introducción:El riesgo cardiometabólico(RCM),es el conjunto de alteraciones metabólicas y clínicas que incrementan la probabilidad de desarrollar enfermedades cardiovasculares y diabetes tipo2. Objetivo:Evaluar el riesgo cardiometabólico en adultos residentes de México.Materiales y métodos:Los datos de los participantes fueron obtenidos de la encuesta nacional de Salud y Nutrición, 2022(ENSANUT), el muestro fue probabilístico y estratificado, se obtuvieron 15 ml de sangre en ayuno, por medio de punción venosa, se obtuvieron los niveles de laboratorio, se realizó la medición de medidas antropométricas, para la formulación de índices antropométricos, la muestra estuvo conformada por 1876 adultos de 18 a 78 años, residentes de México, que desearon participar y firmaron el consentimiento informado, de acuerdo con los criterios se eliminó todas las encuestas incompletas o que no presentaron niveles de laboratorio, los datos fueron analizados con estadística descriptiva en el programa SPSS26. Resultados:Se encontró que de acuerdo con el IMC el 43.1% presenta obesidad, 34.2% sobrepeso, 21.3% normopeso y 1.4% desnutrición, el 90.5% presenta RCM, la media del índice VAI fue de 3.10 ±2.66, LAP 76.65 ±69.29, TyG 8.88 ± 0.61, ABSI 0.81 ±0.05 y BRI 5.83 ±2.13. Conclusión: Se encontró que la prevalencia de RCM fue mayor, seguido de obesidad y sobrepeso, de acuerdo con los índices antropométricos la media de los valores fue superior a los valores reportados.', 5, 'Aceptado', '2025-09-27 18:07:13', '2025-10-03 20:37:29', 1, ''),
(95, 181, 'Daniela Antonio Arrazola', 'Riesgo cardiometabólico en adultos mexicanos', 'Biaani Concepción Arcega López \nMaría Concepción Aguilar Martínez \nEduardo García Morales\nLuz María Quirino Vela', 'Benemérita Universidad de Oaxaca', '', 'Introducción:El riesgo cardiometabólico(RCM),es el conjunto de alteraciones metabólicas y clínicas que incrementan la probabilidad de desarrollar enfermedades cardiovasculares y diabetes tipo2. Objetivo:Evaluar el riesgo cardiometabólico en adultos residentes de México.Materiales y métodos:Los datos de los participantes fueron obtenidos de la encuesta nacional de Salud y Nutrición, 2022(ENSANUT), el muestro fue probabilístico y estratificado, se obtuvieron 15 ml de sangre en ayuno, por medio de punción venosa, se obtuvieron los niveles de laboratorio, se realizó la medición de medidas antropométricas, para la formulación de índices antropométricos, la muestra estuvo conformada por 1876 adultos de 18 a 78 años, residentes de México, que desearon participar y firmaron el consentimiento informado, de acuerdo con los criterios se eliminó todas las encuestas incompletas o que no presentaron niveles de laboratorio, los datos fueron analizados con estadística descriptiva en el programa SPSS26. Resultados:Se encontró que de acuerdo con el IMC el 43.1% presenta obesidad, 34.2% sobrepeso, 21.3% normopeso y 1.4% desnutrición, el 90.5% presenta RCM, la media del índice VAI fue de 3.10 ±2.66, LAP 76.65 ±69.29, TyG 8.88 ± 0.61, ABSI 0.81 ±0.05 y BRI 5.83 ±2.13. Conclusión: Se encontró que la prevalencia de RCM fue mayor, seguido de obesidad y sobrepeso, de acuerdo con los índices antropométricos la media de los valores fue superior a los valores reportados.', 5, 'Aceptado', '2025-09-27 18:07:15', '2025-10-03 15:56:32', 1, ''),
(96, 186, 'Arcega Lopez Biaani Concepcion', 'Índices antropométricos para determinar el Riesgo Cardiometabólico en adultos, residentes de Oaxaca', 'Aguilar Martinez María Concepción \nAntonio Arrazola Daniela\nGarcía morales Eduardo\nQuirino Vela Luz Maria', 'Benemérita universidad de  oaxaca', 'Benemérita universidad de Oaxaca', 'Introducción: El riesgo cardiometabólico (RCM), es  la probabilidad de desarrollar enfermedades cardiovasculares y diabetes mellitus tipo 2, debido a la presencia de factores de riesgo cardiometabólico. Objetivo Determinar el riesgo cardiometabólico a través de índices antropométricos en adultos . Materiales y métodos: Los datos de los participantes fueron obtenidos de la encuesta nacional de Salud y Nutrición, 2022 (ENSANUT), el muestro fue probabilístico y estratificado, se obtuvieron 15 mililitros de sangre en ayuno, por medio de punción venosa, se obtuvieron los niveles de laboratorio, se realizó la medición de medidas de peso, talla y circunferencia de cintura, la muestra estuvo conformada por 66 adultos de 18 a 78 años,  residentes de la Ciudad de Oaxaca, que desearon participar y firmaron el consentimiento informado, de acuerdo con los criterios se eliminó todas algunas encuestas, los datos fueron analizados con estadística descriptiva en el programa SPSS 26. Resultados: de acuerdo a los resultados encontramos que de acuerdo con el índice de RCM el total de los participantes lo presentaron100%, de acuerdo con el IMC se encontró que el 47%presenta obesidad, 28.8%sobrepeso y el 24.2%normopeso, de acuerdo con índices antropométricos la media de TyG fue de 8.93±0.63, TyG*IMC 261.83 ± 52.3yTyG*CC 869.27±131.64. Conclusión: Se encontró que la prevalencia de obesidad y riesgo cardiometabólico en adultos es alta', 5, 'Aceptado', '2025-09-27 19:11:53', '2025-10-03 20:46:20', 1, ''),
(97, 139, 'Miguel Angel San Pablo Juarez', 'Diseño de un detector de posición de arterias en la muñeca usando Tomografía de Impedancia Eléctrica para aplicaciones en gasometría.', 'María Montserrat Oropeza Saucedo\nEnrique López Pérez\nJuan Pablo Aburto Espinoza', 'Universidad Interamericana', 'Universidad Interserrana de Puebla - Chilchotla', 'En este trabajo se presenta el diseño de un sistema electrónico que combina la medición de tomografía de impedancia eléctrica, la bioimpedancia y el procesamiento de imágenes para producir un escáner de arterias en la superficie de la muñeca, con aplicaciones en el método de medición de gasometría como la prueba de Allen, que consiste en la palpación para localización y preparación. Se presenta un sistema electrónico y de software para la realización de la localización, validado mediante una celda de prueba, así como un modelo de visualización de arteria-músculo-piel-nervio. Adicionalmente se presenta una simulación de la aplicación utilizando modelos de elemento finito como referencia para la localización espacial de la vena en dos dimensiones. Finalmente se discuten algunas consideraciones de propiedades a tomar en cuenta en la localización como la frecuencia, la conductividad eléctrica y las cuestiones éticas.', 4, 'Aceptado', '2025-09-28 01:06:09', '2025-09-28 16:56:33', 1, 'tomografía de impedancia eléctrica,bioimpedancia,dispositivo médico,ingeniería biomédica,gasometría'),
(98, 194, 'Eduardo García Morales', 'La Alimentación como Factor Determinante del Rendimiento y Bienestar Estudiantil: Un Análisis de Desafíos, Impacto y Estrategias en la Facultad de Medicina y Cirugía (BUO)', 'Aguilar Martínez María Concepción \nBiaani Concepción Arcega López \nDaniela Antonio Arrazola\nLuz María Quirino Vela', 'Benemérita universidad de Oaxaca, Facultad de medicina y Cirugía (BUO)', 'Benemérita universidad de Oaxaca, Facultad de medicina y Cirugía (BUO)', 'La nutrición es un pilar cognitivo, pero su efectividad depende de factores del entorno estudiantil. Este estudio analiza cómo la gestión del tiempo, el ambiente y, crucialmente, el criterio de elección alimentaria, se correlacionan con el rendimiento académico en la Facultad de Medicina BUO. \n\nSe aplicó una encuesta que evaluó un amplio espectro de factores: hábitos nutricionales, criterios de elección, estrés y rendimiento académico. El instrumento se distribuyó estratégicamente en cuatro grupos de clase de tres generaciones (2ª, 3ª y 4ª) para diversificar resultados..  \n\nAunque factores como escasez de tiempo y el estrés influyen, el criterio de elección alimentaria fue el predictor individual más poderoso del éxito. Más del 70% de los estudiantes guiados por \"conveniencia\" o \"sabor\" reportaron bajas calificaciones (<8.0). Por el contrario, aquellos que prefieren el \"valor nutricional\" reportaron un aumento de calificaciones (8–9). \n\nEste estudio responde la pregunta estudiantil: \"¿Por qué me siento cansado si descanso, camino y me alimento todos los días?\". La respuesta yace principalmente en la calidad de lo que se consume, destacando el entorno, tiempo y más. Reconocer esto ofrece una herramienta de progreso cuyo alto impacto se demuestra en los beneficios directos de una nutrición consciente: mayor vitalidad, mejora en la concentración y un incremento en el rendimiento en exámenes.', 5, 'Aceptado', '2025-09-28 02:15:58', '2025-10-03 20:31:40', 1, 'Rendimiento Académico,Elección de Alimentos,Estudiantes de Medicina,Nutrición,Estrés Académico'),
(99, 202, 'Erick Armando López Ramírez', 'Diseño, Fabricación y Caracterización de un Interferómetro de Fabry–Perot con Soporte Impreso en 3D para Aplicaciones de Sensado Óptico', '', 'Universidad de Guanajuato, División de Ingenierías, Departamento de Ingeniería en Comunicaciones y Electrónica, Salamanca, México', '', 'En este trabajo se presenta el diseño, fabricación y caracterización de un interferómetro de Fabry–Perot (FPI) externo con un método de construcción simplificado y de bajo costo. El dispositivo fue elaborado mediante impresión 3D en PLA para el soporte de alineación y con un sistema de fijación magnética que asegura la coaxialidad de fibras monomodosin necesidad de micro-posicionadores costosos. El sistema demostró ser reproducible, rápido de ensamblar y capaz de generar espectros claros, lo que valida la viabilidad de este diseño para aplicaciones de sensado óptico, desplazamiento y mediciones de índice de refracción. Además, se proponen mejoras en el acabado superficial de las piezas impresas y en la estabilidad del soporte, con el fin de incrementar la precisión en futuras versiones.', 1, 'Aceptado', '2025-09-28 03:46:49', '2025-09-29 20:17:59', 1, 'Interferómetro Fabry–Perot,Sensores de fibra óptica,Impresión 3D'),
(100, 171, 'Enrique Lopez Perez, Gabriel Romero Rodriguez', 'ROBOT CARTESIANO', 'Belén Contreras Flores, Rafael Flores Reyes, Gérardo Ulises Díaz Arango, Angel Hernández Ramírez y Rodrigo Alder Pérez Marin', 'UNIVERSIDAD POLÍTICA DE AMOZOC', 'CENTRO UNIVERSITARIO INTERAMERICANO', 'Diseño y construcción de un robot cartesiano para la enseñanza de automatización industrial.\nEn el presente trabajo se expone el diseño, construcción y análisis de rendimiento evaluado bajo la métrica de carga máxima de un robot cartesiano de tres grados de libertad, concebido para su aplicación en la enseñanza de automatización industrial y en la supervisión de hortalizas. Para su implementación se emplearon perfiles de aluminio de 2 pulgadas y motores a pasos NEMA 17. Asimismo, se presenta el modelo tridimensional desarrollado en SolidWorks y el análisis de carga máxima realizado mediante las herramientas de elementos finitos del mismo software. El robot cartesiano está equipado con dos efectores finales intercambiables: una pinza y un pulverizador de riego. Esta configuración le permite ser utilizado tanto en tareas de supervisión de cultivos hortícolas como en el mantenimiento de jardines urbanos. Una de las principales ventajas del prototipo es su bajo costo de construcción, sin dejar de cumplir con los requerimientos fundamentales de un robot industrial.', 2, 'Aceptado', '2025-09-28 18:27:32', '2025-10-02 16:55:48', 2, ''),
(101, 204, 'Hector Sebastián Jimenez Jimenez', 'Plataforma Web de Inclusión Financiera Global: Pagos Interoperables (Interledger) y Donaciones con Bajas Comisiones', 'Danna Lisseth Martínez Monterrubio\nJesús Jovanni Mendoza Juárez\nJared Peralta Silva', 'FASBIT', '', 'Este proyecto presenta una aplicación web pionera para democratizar las transacciones internacionales, abordando las altas comisiones bancarias mediante la implementación de los protocolos Interledger (ILP) y Open Payments. La plataforma permite a los usuarios realizar pagos transfronterizos con comisiones mínimas, asegurando una alta interoperabilidad entre diferentes redes de pago. Se exploran los beneficios de la liquidación de pagos en tiempo real, la gestión avanzada de liquidez y la trazabilidad de las transacciones. Como valor añadido con impacto social, la aplicación incorpora un módulo de donaciones internacionales a instituciones verificadas, permitiendo la financiación de causas legítimas con metas claras y transparencia total en el flujo del dinero. Finalmente, se incluye la funcionalidad de Split Payments que facilita la división de pagos entre múltiples cuentas, ampliando las posibilidades de uso en el comercio y la colaboración. El trabajo detalla la arquitectura técnica, los desafíos de cumplimiento normativo y el potencial de la tecnología de pagos abiertos para fomentar la inclusión financiera global y la filantropía digital.', 4, 'Rechazado', '2025-09-29 00:43:48', '2025-09-29 18:49:12', 1, 'Pagos,Transacciones,Inclusión financiera,FinTech,Inclusión Financiera'),
(102, 190, 'Romero-Rodríguez Gabriel', 'Diseño, manufactura, instrumentación y control de un robot de 5 grados de libertad para aplicaciones didácticas en ingeniería', 'López-Pérez Enrique, Huerta-Delino Emmanuel, Rodríguez-Fernández Alberto', 'Universidad Politécnica de Amozoc', '', 'Este artículo presenta el diseño, manufactura y control de un robot antropomórfico de cinco grados de libertad, concebido como plataforma didáctica para la formación en Ingeniería Mecatrónica, Robótica y Control. Su propósito es ofrecer a los estudiantes una herramienta práctica que facilite la comprensión de fundamentos robóticos mediante experimentación directa. El diseño mecánico prioriza modularidad y facilidad de ensamblaje, utilizando polímeros ligeros y resistentes optimizando la relación peso-carga útil. La manufactura es prototipado rápido en 3D, lo que asegura precisión dimensional en eslabones y articulaciones para un desempeño cinemático confiable. La instrumentación integra servomotores DC de alto torque, controlados por modulación de ancho de pulso, junto con sensores de posición y una unidad microcontroladora avanzada que coordina drivers de potencia, configurando un sistema de lazo cerrado. El control automático constituye el núcleo del trabajo. Se aplican algoritmos de cinemática directa e inversa para la ejecución de trayectorias y rutinas, mientras que el control articular emplea reguladores PID, con opción de incorporar técnicas avanzadas como control por espacio de estados o adaptativo. Pedagógicamente, la plataforma permite validar modelos cinemáticos y dinámicos, implementar software de control en tiempo real y analizar el rendimiento conjunto de hardware y software.', 4, 'Aceptado', '2025-09-29 16:42:18', '2025-09-30 02:19:33', 1, 'Plataforma didáctica,Robótica antropomórfica,Prototipado rápido 3D,Cinemática y dinámica,Control automático'),
(103, 210, 'Kevin Isau Bravo Cruz', 'RELACIÓN DEL SÍNDROME DE BURNOUT CON CAMBIOS METABÓLICOS EN PARAMÉDICOS DE LA CIUDAD DE OAXACA.', 'Violeta Ríos Trujillo, Aranza Vázquez Pinelo, Karen Melissa Hernández, Alejandra Vásquez Bolaños, Karla Citlali Moreno García, Luz María Quirino Vela, Elizabeth Cruz Altamirano, Camila Martínez Curiel, Juan Alpuche.', 'Facultad de Medicina y Cirugía UABJO.', '', 'El síndrome de Burnout (BO) es la respuesta al\nestrés laboral crónico que afecta tanto la salud mental como física. Descrita a partir de sus 3 dimensiones: cansancio emocional, despersonalización y una baja realización personal, el nivel de estrés asociado al trabajo es el punto clave en su manifestación. Es frecuente en profesionales de la salud como el personal paramédico. Tras el estudio se encontró que en la población estudiada que presenta BO si tiene diferencias en sus biomarcadores metabólicos, glucosa, triglicéridos, VLDL e IA siendo mas altos que la población sin BO, mientras el HDL mas bajo.', 5, 'Aceptado', '2025-09-29 17:12:58', '2025-10-03 14:45:17', 1, 'Síndrome de Burnout,Paramédicos,Oaxaca'),
(104, 80, 'Tony Galindo Avila', 'DESARROLLO DE PROTOTIPO DE REALIDAD VIRTUAL PARA FAVORECER LA ESTIMULACIÓN DE LOS SENTIDOS EN EL PRESENTE', 'Marco Antonio Sanjuan-Santiago, Jorge Fernando Ambros-Antemate, Carlos Lastre-Dominguez, Guillermina Vivar-Estudillo', 'Facultad de Sistemas Biológicos e Innovación Tecnológica', 'Consultorio de Sanjuan Psicología, Tecnológico Nacional de México, Instituto Tecnológico de Oaxaca', 'La percepción sensorial constituye un elemento central en la construcción de experiencias conscientes y significativas. Desde la perspectiva humanista y de la psicología Gestalt, los cinco sentidos son fundamentales para favorecer la integración de sentimientos y percepciones en el presente.\nEn este contexto, se desarrolló el prototipo de realidad virtual diseñado para estimular los sentidos y promover la conciencia plena a través de experiencias inmersivas. El prototipo fue desarrollado usando Unity y Visual Studio aplicando la metodología ágil SCRUM. Este enfoque se centró en la retroalimentación directa de un profesional en psicología, lo que permitió iterar el diseño de los entornos virtuales y adaptarlos de forma continua a las necesidades terapéuticas.\nEl resultado principal es la creación de un prototipo de sistema que integra actividades guiadas de respiración junto con estímulos multisensoriales que inducen calma, concentración y conexión con el aquí y el ahora.', 4, 'Aceptado', '2025-09-29 17:13:22', '2025-09-30 02:32:01', 1, ''),
(105, 208, 'Ing. José Luis Márquez López', 'MODELACIÓN Y ESTUDIO DE LAS PROPIEDADES ELECTRÓNICAS Y ÓPTICAS DE LaCoO3 UTILIZANDO TEORÍA DEL FUNCIONAL DE LA DENSIDAD', 'Ing. Itzel Ortiz Hernández \nDr. Lorenzo Tepech Carrillo', 'Facultad de Sistemas Biológicos e Innovación Tecnológica', 'UABJO', 'Las perovskitas tipo ABO₃ constituyen una familia de materiales con gran relevancia científica y tecnológica, debido a la diversidad de propiedades que presentan y a sus potenciales aplicaciones que van desde la electrónica, hasta  la conversión de energía. Su versatilidad estructural permite ajustar parámetros clave como el gap electrónico, la conductividad iónica y las propiedades ópticas, lo que las convierte en candidatas atractivas para baterías de estado sólido, materiales termoeléctricos y dispositivos operando en ambientes extremos. En este trabajo se realiza la modelación y análisis de las propiedades estructurales, electrónicas y opticas de perovskitas ABO₃ mediante Teoría del Funcional de la Densidad (DFT), empleando el código CASTEP en Materials Studio. Específicamente se estudió la estructura de bandas, la densidad de estados (DOS), las propiedades ópticas y dieléctricas, las cuales nos permitirán estimar propiedades termoeléctricas. En este trabajo, se toma como caso de estudio al LaCoO₃, evaluando sus fases cúbica y romboédrica, para este estudio se utilizó el funcional GGA+U, que permite describir de forma muy precisa los estados electrónicos correlacionados de los iones de transición. Los resultados permiten establecer vínculos entre estructura cristalina y propiedades físicas, aportando información valiosa para el diseño de materiales para aplicaciones en nuevas tecnologías energéticas y electrónicas.', 2, 'Aceptado', '2025-09-29 19:45:52', '2025-10-02 16:53:52', 1, ''),
(106, 133, 'Christopher Salvador Martínez Martínez', 'Árboles de Markov', '', 'Estudiante', '', 'Este trabajo aborda el estudio de los números de Markov y sus propiedades a través de la construcción de distintas estructuras gráficas. Se parte de la teoría de gráficas y árboles, destacado el árbol de Markov, donde cada nodo corresponde a una terna solución de la ecuación de Markov. Se muestra que todos los números de Markov aparecen como máximo de alguna terna y que dichas ternas son coprimos por pares.\n\nAsimismo, se establece la relación entre los números de Markov y las sucesiones de Fibonacci y de Pell, mostrando que todo número de Fibonacci y de Pell con índices impares son números de Markov.', 3, 'Aceptado', '2025-09-29 22:45:38', '2025-09-30 18:42:06', 1, 'Árbol de Markov, Ternas de Markov, Números de Markov');
INSERT INTO `resumenes` (`id`, `autor_id`, `autor_principal`, `titulo`, `coautores`, `adscripcion1`, `adscripcion2`, `resumen_texto`, `area_id`, `estatus`, `fecha_envio`, `fecha_ultima_modificacion`, `intento_envio`, `palabras_clave`) VALUES
(107, 214, 'Hector Sebastian Jimenez Jimenez', 'Plataforma Web de Inclusión Financiera Global: Pagos Interoperables (Interledger) y Donaciones con Bajas Comisiones', 'Danna Lisseth Martínez Monterrubio\nJared Peralta Silva\nJesús Jovanni Mendoza Juárez', 'FASBIT', '', 'Este proyecto presenta una aplicación web pionera para democratizar las transacciones internacionales, abordando las altas comisiones bancarias mediante la implementación de los protocolos Interledger (ILP) y Open Payments. La plataforma permite a los usuarios realizar pagos transfronterizos con comisiones mínimas, asegurando una alta interoperabilidad entre diferentes redes de pago. Se exploran los beneficios de la liquidación de pagos en tiempo real, la gestión avanzada de liquidez y la trazabilidad de las transacciones. Como valor añadido con impacto social, la aplicación incorpora un módulo de donaciones internacionales a instituciones verificadas, permitiendo la financiación de causas legítimas con metas claras y transparencia total en el flujo del dinero. Finalmente, se incluye la funcionalidad de Split Payments que facilita la división de pagos entre múltiples cuentas, ampliando las posibilidades de uso en el comercio y la colaboración. El trabajo detalla la arquitectura técnica, los desafíos de cumplimiento normativo y el potencial de la tecnología de pagos abiertos para fomentar la inclusión financiera global y la filantropía digital.', 4, 'Aceptado', '2025-09-29 23:33:39', '2025-09-30 02:11:23', 1, 'Fintech,Inclusión Financiera,Tecnologías de pago'),
(108, 148, 'Castellanos Hernández Dalia Ivet', 'Asociación entre Vacunas COVID-19 de Ácidos Nucleicos e Infarto Agudo de Miocardio en Adultos: Revisión Sistemática', 'Juan Alpuche', 'Laboratorio de bioquímica, Facultad de Medicina y Cirugía, UABJO', '', 'Objetivo: Determinar si existe asociación entre la administración de vacunas COVID-19 de DNA/RNA y la incidencia de infarto agudo de miocardio (IAM) en individuos de 18 a 80 años.\nMétodos: Revisión sistemática siguiendo guías PRISMA 2020. Se realizó búsqueda exhaustiva en múltiples bases de datos desde diciembre 2020 hasta septiembre 2025. Se incluyeron estudios que evaluaron vacunas mRNA (Pfizer/BioNTech, Moderna) y DNA (AstraZeneca) en adultos 18-80 años con IAM como desenlace primario.\nResultados: Se incluyeron 27 estudios (>141 millones de individuos, >130,000 casos IAM) de 12 países. Los estudios poblacionales grandes (n=12, >100,000 participantes) predominantemente no encontraron asociación significativa entre vacunación y IAM. Un estudio sueco (8.1 millones) reportó efecto protector para terceras dosis (HR 0.81; IC 95%: 0.74-0.89). Solo un estudio de Malasia (22.2 millones) encontró aumento significativo del riesgo para Pfizer (IRR 1.16; IC 95%: 1.02-1.32). Los estudios de casos-control y reportes individuales (n=15) sugirieron asociaciones temporales, principalmente en las primeras 72 horas post-vacunación.\nLa incidencia reportada varió significativamente: Hong Kong 47/millón, Inglaterra ~829/millón. Los reportes de casos individuales (n=12) consistentemente describieron IAM dentro de 1-10 días post-vacunación, principalmente en hombres jóvenes con arterias coronarias normales.', 5, 'Aceptado', '2025-09-30 00:35:08', '2025-10-03 15:52:11', 1, ''),
(109, 216, 'Jessica Nohemí Figueroa Ramírez', 'Imágenes de profundidad aplicadas a la caracterización morfológica del pie plano como herramienta de apoyo al diagnóstico', 'Juan Manuel Sierra Hernández, Daniel Torres González y Ángel Díaz Pacheco', 'Universidad de Guanajuato', '', 'El pie plano es una alteración biomecánica caracterizada por la disminución o ausencia del arco longitudinal medial, cuya prevalencia se incrementa por factores como el sobrepeso y la obesidad, especialmente en la población infantil y adolescente en México. Entre los métodos de evaluación clínica más comunes se encuentra la huella plantar, una técnica asequible que depende de la correcta aplicación de índices como Staheli o Chippaux por parte del especialista. Este trabajo presenta el desarrollo de una herramienta de apoyo al diagnóstico preventivo del pie plano a partir de imágenes de profundidad obtenidas con una cámara estéreo de bajo costo, un arreglo óptico simple y técnicas de procesamiento digital. A diferencia de los métodos tradicionales, se propone explorar una forma de normalización de los datos mediante una medida relativa entre el volumen bajo el arco y el área de la huella, con el fin de mejorar la comparación entre individuos. La propuesta busca ofrecer una alternativa accesible y no invasiva que, además de aplicarse en la consulta presencial, pueda integrarse en esquemas de telemedicina. Con ello se pretende acercar el diagnóstico temprano a comunidades con acceso limitado a especialistas, sin sustituir la valoración médica, sino reforzando la labor del profesional de la salud', 5, 'Aceptado', '2025-09-30 04:38:18', '2025-10-03 14:39:43', 1, 'Visión por computadora,Pie plano,Imagen de profundidad'),
(110, 215, 'EVER YAEL BAUTISTA HERNANDEZ', 'ESTUDIO DE PRIMEROS PRINCIPIOS DE LA ESTABILIDAD DE NITRUROS METÁLICOS CRN, MON Y WN.', '', 'EDMUNDO LÓPEZ APREZA', 'LORENZO TEPECH CRRILLO.', 'Los nitruros metálicos de transición constituyen una clase de compuestos de gran interés debido a sus destacadas propiedades mecánicas, térmicas y químicas, que los hacen atractivos para aplicaciones en recubrimientos protectores y condiciones de trabajo extremas. Entre ellos, los nitruros (CrN, MoN y WN) se han identificado como materiales con potencial en la industria de herramientas de corte, dispositivos electrónicos y recubrimientos resistentes al desgaste.\nEl estudio de estos compuestos a nivel fundamental requiere el uso de herramientas teóricas capaces de describir sus propiedades electrónicas y estructurales con alta precisión. En este sentido, los cálculos de primeros principios basados en DFT, utilizando pseudopotenciales ultrasuaves (PBE, LDA y GGA), representan una metodología idónea para examinar la estabilidad relativa de distintas fases cristalinas y proporcionar información que complemente la investigación experimental.\nDentro de las posibles configuraciones estructurales de los nitruros metálicos, las fases cúbicas ofrecen un marco de análisis particularmente relevante. En el caso del CrN, MoN y WN pueden describirse mediante fases cúbicas derivadas de los mismos grupos espaciales, con alternancia sistemática entre las posiciones de los átomos metálicos y de nitrógeno. La exploración teórica de estas estructuras permite establecer un marco coherente para el estudio de su estabilidad mecánica, termodinámica y óptica.', 2, 'Aceptado', '2025-09-30 05:24:43', '2025-10-02 16:54:19', 1, 'propiedades opticas, mecanicas y termicas'),
(113, 221, 'Josué Vladimir Reyes Urenda', 'Segmentación de Imágenes Dermatoscópicas de Lesiones Cutáneas mediante Técnicas Clásicas de Procesamiento de Imágenes para Apoyo en el Diagnóstico Médico', 'José Edgar Lara Ramirez', 'FASBIT - UABJO', 'FASBIT - UABJO', 'Este trabajo presenta el desarrollo de un sistema para la segmentación automática de heridas en imágenes médicas mediante técnicas clásicas de procesamiento digital de imágenes. El objetivo es apoyar el diagnóstico y seguimiento clínico de lesiones, reduciendo la subjetividad y el tiempo asociados a la segmentación manual. El sistema fue implementado en Python y OpenCV, con una interfaz gráfica en Tkinter que permite la interacción con las imágenes y las máscaras de referencia.\nSe probaron diferentes enfoques, como segmentación en el espacio de color HSV, binarización, filtros de suavizado, operaciones morfológicas y análisis geométrico. Tras varias versiones iterativas, se diseñó un pipeline final que combina preprocesamiento (contraste, brillo y filtrado), binarización, operaciones morfológicas, detección de contornos y generación de máscaras comparables con segmentaciones expertas.\nEl método alcanzó un Accuracy promedio de 91.11 %, IoU de 70.09 %, Precisión de 94.29 %, Recall de 74.78 % y F1 Score de 80.20 %, mostrando un buen equilibrio entre exactitud y confiabilidad, aunque con limitaciones en la detección completa de las regiones afectadas. Se concluye que, pese a no emplear aprendizaje profundo, la propuesta ofrece una solución eficaz y accesible para la segmentación de heridas, representando una base sólida para futuras mejoras con técnica de umbral dinámico basado en histograma.', 4, 'Aceptado', '2025-09-30 17:24:42', '2025-09-30 19:56:31', 1, 'Procesamiento de Imágenes,Segmentación,Imágenes Dermatoscópicas,Técnicas Clásicas'),
(114, 221, 'Ing. Josué Vladimir Reyes Urenda', 'Juegos Serios en la Rehabilitación de Mano: Una Revisión de la Literatura', 'Dra. María del Pilar Beristain Colorado; Dr. Jorge Fernando Ambros Antemate', 'FASBIT - UABJO', '', 'La rehabilitación de la mano constituye un reto clínico debido a su complejidad anatómica y funcional, así como a los altos índices de abandono en los tratamientos convencionales. Los juegos serios aplicados a la rehabilitación física integran dinámicas lúdicas con objetivos terapéuticos, posicionándose como una alternativa innovadora para incrementar la motivación, la adherencia y los resultados funcionales en pacientes con lesiones de mano. \nEsta revisión recopila estudios publicados en bases de datos como PubMed, IEEE y Google Académico con el propósito de identificar tendencias en el diseño, implementación y evaluación de juegos serios dirigidos a la rehabilitación de la mano. Los hallazgos evidencian un uso creciente de tecnologías interactivas, incluyendo sensores de movimiento, realidad virtual y plataformas accesibles de bajo costo, que muestran un impacto positivo en la recuperación funcional. \nEn conjunto, los resultados sugieren que los juegos serios no sustituyen, sino que complementan las terapias tradicionales, ofreciendo un campo prometedor para la innovación clínica y la investigación interdisciplinaria en el ámbito de la rehabilitación de la mano.', 4, 'Rechazado', '2025-09-30 17:35:38', '2025-09-30 19:55:22', 1, 'Juegos serios,Rehabilitación de mano,Tecnologías Interactivas'),
(116, 225, 'Daniela Jimena Martinez Perez', 'Instrumentación Avanzada de Termopares en un Secador Solar Doméstico Mediante una Placa de Desarrollo ESP32', 'Francisco Javier Ramos Mendez', 'Facultad de Sistemas Biologicos e Innovacion Tecnologica, Universidad Autonoma Benito Juarez de Oaxaca', '', 'El presente proyecto aborda el diseño e implementación de un sistema de monitorización térmica para secadores solares domésticos, utilizando la placa de desarrollo ESP32 como microcontrolador central. El objetivo principal es optimizar la adquisición y gestión de datos de temperatura interna en múltiples puntos estratégicos del secador. Mediante la instrumentación de termopares, se busca una recolección de mediciones precisa y simultánea, consolidando la información en una única interfaz de visualización de datos. Esta propuesta no solo eleva la eficiencia en el proceso de monitorización, sino que también sienta las bases para la transformación de secadores solares convencionales en sistemas \"inteligentes\". Dicha evolución contribuirá significativamente a la optimización del secado y aprovechamiento de productos agrícolas, especialmente frutos secos, impulsando la sostenibilidad y la eficiencia energética en el ámbito doméstico.', 2, 'Aceptado', '2025-09-30 18:54:06', '2025-10-02 16:52:32', 1, 'Secador solar,ESP32,Termopares,Energia Solar,Sistemas Inteligentes'),
(117, 229, 'Lisandro Jiménez Cruz', 'EduPay: Plataforma de Micropagos en Tiempo Real para Tutorías y Educación en Línea', 'José Luis Batres Fierro,Alan Daniel Ortega Ramos, Victor Manuel Ramírez Juarez', 'Facultad de Sistemas Biológicos e Innovación Tecnológica', '', 'Los modelos actuales de educación en línea se basan en pagos por cursos completos o suscripciones, lo que genera dos problemas principales: \n1.-Para los estudiantes, supone altos costos y barreras de acceso cuando solo requieren micro-asesorías o resolver dudas específicas. Además, la falta de cobros transparentes en tiempo real limita la confianza. \n2.-Para los tutores, especialmente en regiones con baja bancarización, existen dificultades para recibir pagos internacionales de forma rápida y con bajas comisiones, lo que limita sus oportunidades.\n\nEduPay propone una plataforma de micropagos en tiempo real que permite pagar solo por el tiempo y contenido consumido, con un contador visible que genera transparencia. Para los tutores, ofrece pagos instantáneos y acceso global sin infraestructura bancaria.\n\nLa solución se basa en Interledger Protocol (ILP) y STREAM/SPSP para habilitar pagos “pay-as-you-go” continuos. Open Payments y payment pointers permiten identificación universal y direccionamiento entre billeteras.\n\nLa arquitectura tiene tres capas: Front-end (contador y recibos automáticos), Back-end (orquestación de sesiones y registro de transacciones) y Pagos e interoperabilidad (integración con protocolos de micropagos). Las funciones clave incluyen pago por uso, recepción instantánea y soporte multi-moneda y transfronterizo.\n\nSe espera que esta arquitectura incremente el acceso flexible a tutorías y optimice la monetización de micro-servicios educativos.', 4, 'Aceptado', '2025-10-01 04:19:37', '2025-10-01 13:35:29', 2, 'micropagos,educacion en linea,pagos instantaneos,tutorias monetizadas'),
(118, 230, 'Ivonne Guadalupe Melchor Mijangos', 'Trueque – Moneda de Transformación', '•	Ing. Francisco Javier Melchor Lopez\n•	Uziel Ademir Hernández Cruz\n•	David Gonzalo Sanchez Ramirez\n•	Antonio Manuel Garcia Morales\n•	Cesar Adriel Morales', 'Área Tecnológica y de Innovación Digital', 'Área de Ciencias Económicas y Financieras', 'El proyecto “Trueque – Moneda de Transformación” (C-Turbo) busca resolver las limitaciones de las transferencias internacionales, como comisiones altas, procesos lentos y conversiones manuales de divisas. Su propuesta consiste en un sistema que convierte automáticamente la moneda enviada en la divisa que recibe el destinatario, sin tarifas visibles, priorizando rapidez, seguridad y claridad. La arquitectura tecnológica se basa en un frontend en React/Vite/TypeScript, un backend en Node.js con Express, bases de datos PostgreSQL/MongoDB y un módulo de conversión que ejecuta los intercambios. Entre sus funciones clave están: registro y autenticación de usuarios, historial de transacciones, notificaciones y cifrado de datos.\n\nUn aspecto central es la incorporación de Interledger, tecnología que permite la interoperabilidad entre diferentes redes y monedas, facilitando que las transferencias se realicen sin depender de proveedores únicos. El equipo adoptó un enfoque ágil inspirado en Scrum, con roles definidos (frontend, backend, base de datos, pruebas), ciclos cortos y entrega de un producto mínimo viable.\n\nLos principales retos técnicos incluyen asegurar tasas de conversión en tiempo real, mantener la seguridad y escalabilidad, y garantizar baja latencia. Si se consolida, C-Turbo podría reducir costos de remesas, impulsar el comercio internacional e incrementar la inclusión financiera, transformando la manera en que concebimos las transferencias globales.', 4, 'Aceptado', '2025-09-30 20:57:05', '2025-10-01 13:30:40', 1, 'Economía digital,Seguridad en transacciones,Inclusión financiera,Comercio internacional,Finanzas globales'),
(119, 222, 'Miriam Azalia Luna Bautista', 'Monitoreo autónomo inteligente en cultivos', '', 'Facultad de sistemas biológicos e innovación tecnológica', '', 'Los hogares son parte fundamental del buen funcionamiento de las personas, pues son los lugares de descanso y desconexión, con el creciente avance de la tecnología y la domótica hacerlos aún más cómodos, seguros y sustentables es el futuro cercano.\nGeoGrowNexus es un proyecto innovador que presenta un sistema de sensores integrados con inteligencia artificial con monitoreo en ambientes cerrados y abiertos en tiempo real, monitorea de forma autónoma temperatura, humedad y calidad del aire, así como el riego inteligente de cultivos aeropónicos.\nCon el uso de la app desarrollada se integra la domótica en cultivos urbanos y se consulta de forma rápida y fácil la información recaudada por los sensores y la inteligencia artificial diseñada para tomar decisiones en situaciones, críticas y riego inteligente.\nCon Geo Grow Nexus, aseguramos una casa inteligente sustentable con monitoreo en tiempo real riego inteligente, aplicando la domótica y cultivos hidropónicos, en este proyecto se demuestra como la convergencia de las tecnologías emergentes, puede impulsar la responsabilidad ambiental y mejorar la calidad de vida en procesos de cultivos, Aerop y casas inteligentes.', 4, 'Aceptado', '2025-09-30 21:39:43', '2025-10-01 04:08:05', 1, 'Cultivos aeropónicos, domótica, riego inteligente'),
(121, 172, 'Saraid Tobón Benítez', 'Activación de semáforo inteligente mediante la predicción de redes neuronales LSTM', 'Dr. Tomás Pérez Becerra\n\nDr. Eduardo Sánchez Soto', 'Universidad Tecnológica de la Mixteca', '', 'Este trabajo presenta un modelo de control semafórico inteligente entrenado con datos obtenidos del artículo Modeling Driver Behavior in Road Traffic Simulation (Mecheva, Furnadzhiev y Kakanakov, 2022), los cuales fueron generados mediante el simulador de movilidad SUMO y reflejan patrones correlacionales en la duración óptima de las fases del semáforo. El estudio aborda la problemática de los semáforos urbanos que operan con tiempos fijos, en contraste con la naturaleza dinámica del flujo vehicular, que varía significativamente a lo largo del día y provoca periodos innecesarios de ralentí con efectos negativos en el medio ambiente, la salud y la economía.\n\nPara mitigar estas ineficiencias, se propone un sistema basado en redes neuronales de memoria a corto y largo plazo (LSTM). El modelo fue entrenado para predecir la evolución del tráfico y ajustar de manera dinámica los tiempos de luz verde, anticipándose a los picos de congestión. Los resultados de simulación muestran un desempeño sólido, alcanzando un RMSE de 58.53 y una pérdida de 0.0080, lo que evidencia un buen ajuste respecto a los datos reales.\n\nEste enfoque demuestra que las redes LSTM pueden mejorar la eficiencia del transporte urbano y contribuir a la reducción del consumo de combustible y las emisiones contaminantes, consolidándose como una herramienta eficaz para el desarrollo de infraestructuras de movilidad inteligentes y sostenibles.', 4, 'Aceptado', '2025-09-30 23:25:41', '2025-10-01 13:28:33', 1, 'Semáforo Inteligente, Flujo Vial, SUMO, LSTM,'),
(122, 223, 'Halil Kalev Pineda Alvarez', 'Sistema de Monitorización de Colector Solar (SMCS)', 'Francisco Javier Cruz Agustin', 'Faculta de Sistemas Biológicos e Innovación Tecnológica', '', 'Sistema de Monitorización de Colector Solar (SMCS) desarrollado para el análisis y visualización en tiempo real del rendimiento térmico de colectores solares. Este sistema emplea una cámara térmica para capturar imágenes que son procesadas mediante la biblioteca de visión por computador OpenCV, permitiendo una evaluación detallada y no invasiva de la distribución de temperaturas.\nEl núcleo del SMCS consiste en la lectura de la matriz de datos de la imagen térmica. Cada píxel de esta matriz es procesado a través de un modelo no lineal previamente calculado, que asigna un nivel de temperatura preciso. Este procesamiento genera dos representaciones matriciales de los datos: una matriz que almacena los valores de temperatura por píxel y otra que se traduce en una imagen en escala de grises para una visualización intuitiva. Adicionalmente, se aplica un filtro de falso color, conocido como \"rainbow\", para resaltar las variaciones de temperatura y facilitar la identificación de puntos calientes o fríos.\nLos datos procesados, incluyendo las matrices de temperatura y las imágenes termográficas, son almacenados de forma organizada en una carpeta designada para su posterior análisis. El sistema se complementa con un endpoint dedicado a un panel de control o \"dashboard\". Esta interfaz de visualización de datos permite a los usuarios consultar la temperatura en tiempo real y explorar representaciones gráficas avanzadas del perfil térmico del colector.', 2, 'Aceptado', '2025-10-01 00:07:28', '2026-01-17 22:27:36', 1, 'Automatización,Python,IR'),
(123, 129, 'Adriana Joyce Rodriguez Sanchez', 'Identificación de Emociones Negativas a través de Interfaces Cerebro-Computadora', 'Patricia Batres Mendoza\nErick Israel Guerra Hernández\nChristian Perezcampos Mayoral', 'Laboratorio de Inteligencia Artificial, Robótica y Control', '', 'El estudio de las emociones y su influencia en el comportamiento ha sido de gran interés, especialmente en la identificación de estados negativos como estrés, ansiedad o frustración. Este proyecto plantea un protocolo experimental para analizar cómo el estrés impacta en las emociones, empleando electroencefalografía (EEG) aplicada en una interfaz cerebro-computadora (BCI).\nEl diseño experimental asegura validez científica y replicabilidad, mediante un protocolo controlado que evalúa objetivamente cambios en la actividad cerebral, reduciendo artefactos en el registro. Para la adquisición de señales se utilizó una diadema EEG Emotiv Epoc+ con 14 electrodos distribuidos según el sistema 10-20. Los datos se almacenaron en formato CSV para su análisis posterior con herramientas computacionales.\nEl experimento se estructuró en tres ciclos que alternaron tareas cognitivas estresantes y periodos de relajación, induciendo distintos estados emocionales. Participaron ocho voluntarios bajo condiciones controladas para garantizar consistencia en la recolección.\nLas señales EEG fueron preprocesadas y analizadas con algoritmos de inteligencia artificial, en particular técnicas de aprendizaje automático, con el fin de clasificar emociones negativas según la dinámica cerebral. Los resultados esperados incluyen la identificación de patrones específicos vinculados al estrés y la validación del protocolo como modelo replicable.', 4, 'Aceptado', '2025-10-01 00:08:29', '2025-10-01 04:04:27', 1, 'emociones,estrés,electroencefalografía,Machine Learning,interfaz cerebro-computadora'),
(124, 178, 'Diana Jazmín Casas Del Ángel1', 'Análisis de mejora del control de calidad en biotecnología a través de estadística descriptiva y Lean Manufacturing.', 'Dr. Ernesto Isaac Tlapanco Rios1\nDr. Héctor Plascencia Mora2\nIng. Estephania Jazvi Casas Del Ángel2', 'Universidad de Guanajuato, Departamento de Estudios Multidisciplinarios DEM, Av. Univer-sidad, S/N Col. Yacatitas, 38940 Yuriria, Gto.', 'Universidad de Guanajuato, División de Ingenierías Campus Irapuato Salamanca DICIS, Carretera Salamanca - Valle de Santiago km 3.5 + 1.8 Comunidad de, Palo Blanco, 36787 Salamanca, Gto.', 'El presente estudio analiza por medio de la estadística descriptiva, un proceso de análisis de fallos en la producción de ácidos oligonucleótidos, centrándose en la recopilación y gestión de la información de fallas. El objetivo fue la identificación de los puntos débiles en el registro y análisis de datos de las fallas. Por medio de gráficas estadísticas (histogramas y paretos) se analizaron los datos históricos, para proponer estrategias de mejora en la trazabilidad y reducción de fallas. La metodología consistió en aplicar herramientas de Lean Manufacturing para un reconocimiento del proceso, complementadas con entrevistas al personal, toma de tiempos e interacciones para identificar puntos críticos entre procesos y personal. Los resultados revelaron vulnerabilidades: falta de estandarización, dispersión de datos y protocolos de seguridad insuficientes; estos aumentaban el riesgo de omisiones, interpretaciones erróneas y fallos repetitivos. La creciente complejidad de los sistemas de síntesis y la integración de tecnologías digitales muestran la necesidad de aplicar la trazabilidad, análisis y protección de datos. El estudio demuestra que mejorar la estandarización y aplicación de protocolos de seguridad son esenciales para mitigar vulnerabilidades y apoyar la calidad y seguridad de la producción. Las conclusiones sientan las bases para desarrollar estrategias que refuercen el análisis de fallas y la gestión de la información en la industria de la biotecnología.', 3, 'Aceptado', '2025-10-01 01:23:03', '2025-10-07 04:29:54', 1, 'Gestión de datos,Estadística Descriptiva,Análisis de fallas,Ácidos oligonucleótidos,Lean Manufacturing'),
(125, 234, 'Selma Aketzali Vásquez Arias', 'La infección con Leishmania mexicana modula diferencialmente la vía de las hexosaminas y la O-GlcNAcilación  en macrófagos J774.', 'Gaspar Salas Mario Eduardo1\n Torres Rosas Rafael2\n Argueta Figueroa Liliana3\nMoreno Rodríguez Adriana1\n Pérez Cervera Yobana2', '1.- Facultad de Ciencias Químicas, Universidad Autónoma “Benito Juárez” de Oaxaca, Oaxaca, Oax. 68120, México.', '2.- Centro de Estudios en Ciencias de la Salud y la Enfermedad, Facultad de Odontología, Universidad Autónoma Benito Juárez de Oaxaca, Oaxaca, México. Autr de correspondencia', 'Antecedentes:\nLa leishmaniasis es una enfermedad parasitaria de gran relevancia en salud pública, con entre 1.5 y 2 millones de casos anuales y alrededor de 70 mil muertes. Sus formas clínicas cutánea, mucocutánea y visceral afectan a poblaciones vulnerables, siendo el sureste de México una zona endémica potencial. El parásito Leishmania mexicana debe adaptarse al ambiente intracelular del macrófago, modulando la traducción de proteínas para sobrevivir. La vía de las hexosaminas y la O-GlcNAcilación participan en la polarización de macrófagos y en la respuesta inmune innata. La enzima GFAT, con dos isoformas principales (GFAT1 y GFAT2), es clave en este proceso.\nObjetivo:\nCuantificar la expresión proteica de las isoformas GFAT1 y GFAT2 en macrófagos J774.2 infectados con promastigotes de Leishmania mexicana. \nMétodos:\nSe cultivaron macrófagos J774.2 y se infectaron con promastigotes. Posteriormente, se extrajeron proteínas totales, se cuantificaron mediante BCA y se analizaron por Western blot con anticuerpos específicos para GFAT1 y GFAT2.\nResultados:\nLos macrófagos infectados mostraron un incremento de 2 a 3 veces en GFAT1 respecto al control, mientras que GFAT2 presentó solo un aumento marginal.\nConclusiones:\nLa infección con L. mexicana induce principalmente la expresión de GFAT1, lo que sugiere su papel en la respuesta inmune. La inhibición farmacológica de esta isoforma podría representar una estrategia terapéutica futura.', 5, 'Aceptado', '2025-10-01 01:36:10', '2025-10-02 21:03:14', 1, 'GFAT,Leishmaniasis,O-GlcNAcilación'),
(126, 144, 'Abraham Reyes Castellanos', 'Ilú Aplicación de Remesas Financiera', 'Valentina Leon Hernandez\nSaul Abigael Guerra Rivas\nNahum Santa Ana Ceballos', 'Facultad de Sistemas Biológicos e Ingeniería en Innovación Tecnológica', '', 'Las remesas son cruciales para el desarrollo en Oaxaca, pero su potencial se ve limitado por las altas comisiones, la poca accesibilidad a sucursales físicas y la falta de historial crediticio de las familias.\nIlú es una aplicación móvil diseñada para transformar la recepción y gestión de remesas. Su principal objetivo es reducir la desigualdad financiera a través de la integración con la red Open Payments, logrando tarifas significativamente más bajas que los servicios tradicionales y eliminando la necesidad de traslados a sucursales.\nLa plataforma no solo facilita la recepción de dinero, sino que también promueve la inclusión financiera. Mediante el registro de transacciones digitales, Ilú genera historiales de crédito útiles para las familias, abriendo puertas a servicios financieros formales.\nAdemás, incorpora un asistente virtual basado en Inteligencia Artificial que analiza los patrones de gasto de cada usuario. Esta IA ofrece educación financiera personalizada y recomendaciones de ahorro adaptadas, empoderando a las comunidades para una mejor gestión de sus recursos.\nEl prototipo funcional, desarrollado con una arquitectura escalable (React/Node.js/Express) y un modelo preliminar de IA, ha demostrado su viabilidad técnica. Los resultados preliminares simulan transacciones con ahorros de hasta un 70% en comparación con métodos convencionales.\nEn conclusión, Ilú combina pagos digitales eficientes y análisis inteligente de datos para ofrecer una solución de impacto social', 4, 'Aceptado', '2025-10-01 03:26:24', '2025-10-01 13:27:23', 2, 'Fintech,Pagos Digitales,Presupuesto Inteligente,Inteligencia artificial'),
(127, 238, 'Daniel Pacheco Bautista', 'Cómputo reconfigurable aplicado a la optimización de Sistemas de Energías renovables', 'Atziry Cárdenas Jijón\nFrancisco Aguilar Acevedo\nYuliana García Amaya', 'Dpto. de Ingeniería en Computación, Universidad del Istmo, Campus Tehuantepec, Av. Universidad S/N, 4ª sección de Sta. Cruz Tagolaba, Tehuantepec, Oax., C.P. 70760, México', 'Dpto. de Posgrado en energías renovables, Universidad del Istmo, Campus Tehuantepec, Av. Universidad S/N, 4ª sección de Sta. Cruz Tagolaba, Tehuantepec, Oax., C.P. 70760, México', 'En la última década, las energías renovables, particularmente la solar fotovoltaica y la eólica, han consolidado su papel como alternativas viables y competitivas frente a las fuentes fósiles. Sin embargo, subsisten limitaciones vinculadas con la eficiencia de conversión, la gestión de la intermitencia y la integración masiva a las redes eléctricas. En este contexto, el cómputo reconfigurable basado en FPGAs se perfila como un recurso estratégico debido a su elevada capacidad de procesamiento paralelo, su reconfigurabilidad en tiempo real y su eficiencia energética. En este artículo se presentan las principales aplicaciones emergentes de los FPGAs en los sistemas de energías renovables, profundizando en dos de especial relevancia: el seguimiento del punto de máxima potencia (MPPT), fundamental para mejorar la captación energética bajo condiciones ambientales dinámicas, y la ecualización de arreglos fotovoltaicos, destinada a mitigar pérdidas asociadas con el desbalance y el sombreado parcial.', 2, 'Aceptado', '2025-10-01 04:02:48', '2025-10-02 16:55:08', 1, 'Energías Renovables,FPGAs,Ecualización de irradiancia,MPPT,Sombreado parcial'),
(128, 217, 'José Francisco Delgado Orta', 'Plataformas Tecnológicas para el Corredor Interoceánico del Istmo de Tehuantepec: retos y oportunidades', 'Mayra Diana Ruíz Calderón', 'Universidad del Mar', 'Universidad Internacional del Pacífico', 'El Corredor Interoceánico del Istmo de Tehuantepec (CIIT) es una iniciativa gubernamental y de particulares, creada para promover el desarrollo regional del sureste de México. Para ello, se plantea un escenario del comercio internacional que emplea el transporte multimodal para el traslado de mercancías entre los puertos de Coatzacoalcos Veracruz y Salina Cruz Oaxaca, en vías de emplear la infraestructura portuaria y los sistemas de transporte para procesar las operaciones que implementan los procesos de negocio que son parte de las cadenas de suministro emergentes. En este escenario, los sistemas de información juegan un papel esencial en el registro, la automatización y la ejecución de las transacciones comerciales. Sin embargo, la complejidad estructural de las industrias y sus procesos han dificultado la construcción de plataformas digitales integrales, dirigiendo la producción de estas hacia productos hechos a la medida. A pesar de esta limitante, en el marco de la Industria 4.0, la producción de sistemas inteligentes que brindan el soporte a la toma de decisiones ha añadido valor a los desarrollos tecnológicos. Por tal motivo, estos han dirigido sus esfuerzos hacia la aplicación de los enfoques sistémicos del pensamiento, los cuales representan un área de oportunidad en los requerimientos del CIIT, en vías de producir las herramientas digitales que integren las operaciones de las cadenas de suministro en una plataforma logística multimodal.', 4, 'Aceptado', '2025-10-01 05:00:34', '2025-10-01 13:33:29', 1, 'CIIT,plataformas tecnológicas,comercio internacional,transporte multimodal,cadenas de suministro'),
(129, 236, 'Roberto Saúl Hernández Reyes', 'Hacia un etiquetado de imágenes accesible: una alternativa de código abierto para investigadores y desarrolladores', 'Gerardo Ulises Díaz Arango\nHéctor Vázquez Leal\nEnrique López Pérez\nAlonso Díaz Hernández', 'Universidad Veracruzana', 'Universidad Politécnica de Amozoc', 'En este trabajo se aborda el desarrollo de una aplicación de escritorio para sistemas operativos Windows. Se utilizó el framework Windows Forms de .NET en C#, empleando el entorno de desarrollo integrado (IDE) de Microsoft, Visual Studio 2022.\nEl propósito de esta herramienta es apoyar a los usuarios en el etiquetado automático de imágenes utilizadas para entrenar modelos de inteligencia artificial con fines académicos.\nEsta aplicación carga y utiliza modelos YOLO dentro de su interfaz gráfica intuitiva, con el objetivo de brindar a los usuarios la posibilidad de emplear sus propios modelos entrenados en Python en su propia computadora. De esta manera, los usuarios pueden disponer de una herramienta personal que no solicita información privada ni impone ningún tipo de restricción en el uso o la implementación personal.', 4, 'Aceptado', '2025-10-01 05:09:41', '2025-10-01 13:32:07', 1, 'YOLO,Etiquetado de imágenes,Machine Learning,inteligencia artificial,Clasificación de imágenes'),
(130, 236, 'Roberto Saúl Hernández Reyes', 'VISIÓN ARTIFICIAL EN LA AGRICULTURA: UN ESTUDIO COMPARATIVO SOBRE CONJUNTOS DE DATOS PARA LA DETECCIÓN DE ENFERMEDADES EN CULTIVOS CITRÍCOLAS', 'Gerardo Ulises Díaz Arango\nHéctor Vázquez Leal\nErika Yazmin Teran Bahena\nAlonso Díaz Hernández', 'Universidad Veracruzana', 'Universidad Interamericana', 'La industria de los cítricos posee un impacto positivo en el desarrollo económico de muchos países, en especial en el territorio mexicano. En este articulo se presenta la revisión de 30 estudios recientes. En ellos se profundiza en aspectos clave relacionados con la detección de enfermedades en cítricos, empleando técnicas de inteligencia artificial basadas en el análisis de imágenes, provenientes de bases de datos públicas y privadas. Este trabajo tiene el propósito de examinar, los principales países interesados este tópico, la disponibilidad de las bases de datos, la cantidad de imágenes implementada, la precisión de los resultados y las pruebas de campo realizadas. Asimismo, se analiza el uso de técnicas de aumento de datos y los efectos que estas generan en la precisión de los modelos. Finalmente, se evalúan las métricas de precisión alcanzadas y se discute la relevancia de los resultados para la replicación de los experimentos, reconociendo a los autores originales. Este análisis busca contribuir al\ndesarrollo de soluciones más robustas y replicables en la detección de enfermedades de\ncítricos.', 5, 'Aceptado', '2025-10-01 05:24:54', '2025-10-03 20:49:07', 1, 'Procesamiento de imágenes,enfermedades de citricos,bases de datos,Machine Learning'),
(131, 236, 'Jordi Ortega Figueroa', 'Revisión sistemática de casos de aplicación de nano generadores triboeléctricos para un desarrollo urbano tecnológico y sostenible.', 'Gerardo Ulises Díaz Arango\nHéctor Vázquez Leal\nErika Yazmin Teran Bahena\nAlonso Díaz Hernández', 'Universidad Veracruzana', 'Universidad Interamericana', 'En este artículo se presenta una revisión de las diferentes aplicaciones que la comunidad científica le ha dado a los nanogeneradores triboeléctricos (TENGs), desde el punto aplicativo hasta las ciudades inteligentes. Los TENGs se proyectan como la mayor alternativa para la generación de energía eléctrica limpia; al funcionar bajo los principios de contacto, electrificación e inducción electrostática, son capaces de convertir la energía mecánica de movimientos de diversas fuentes como los provocados por el viento, el constante vaivén de las olas, movimientos humanos o vibraciones en energía eléctrica limpia. De la misma manera en que pueden cosechar energía de movimientos de baja frecuencia, nos dan la opción de utilizarlos como sensores autoalimentados. En este trabajo, se dividen las aplicaciones en distintas áreas del desarrollo urbano: desde transporte inteligente hasta aplicaciones para hogares y escuelas; así como interacciones humano-máquina y el beneficio que se puede obtener en el ámbito de la salud. Finalmente, se discuten los beneficios y las limitaciones de esta tecnología, y se proponen futuras aplicaciones, así como líneas de investigación.', 2, 'Aceptado', '2025-10-01 05:35:51', '2025-10-02 16:55:30', 1, 'nano generadores,efecto triboeléctrico,cosecha de energía,sensores autoalimentados,energía limpia'),
(132, 236, 'Osvaldo Elí Ramos Sánchez', 'Revisión de técnicas de mapeo de entornos con aplicaciones en robots autónomos', 'Gerardo Ulises Díaz Arango\nHéctor Vázquez Leal\nErika Yazmin Teran Bahena\nEnrique López Pérez', 'Universidad Veracruzana', 'Universidad Interamericana', 'El presente trabajo revisa las técnicas de mapeo más  relevantes utilizadas en el ámbito de la robótica móvil,  con un enfoque particular en la implementación de  algoritmos de localización y mapeo simultáneo (SLAM,  por sus siglas en inglés). Se analizan métodos basados  en percepción, como aquellos que emplean sensores  LiDAR, cámaras monoculares y estereoscópicas, así  como enfoques híbridos que combinan diversas  tecnologías. La revisión incluye una discusión sobre los  desafíos actuales, tales como la gestión de entornos  dinámicos, la optimización de recursos  computacionales y la integración de la inteligencia  artificial para mejorar la precisión y eficiencia de los  sistemas. Este trabajo tiene como objetivo  proporcionar una visión integral que facilite el  desarrollo de soluciones innovadoras y robustas en el  campo del mapeo autónomo en robótica.', 4, 'Aceptado', '2025-10-01 05:42:21', '2025-10-01 13:31:30', 1, 'Robots autonomos,Mapeo de entorno,visión computacional,SLAM'),
(136, 243, 'Zuemy Rodríguez Escamilla', 'Vigilancia genómica de la costa de Yucatán: resistoma y elementos genéticos móviles en comunidades microbianas costeras, un enfoque metatranscriptómico', 'Mario Alberto Martínez Núñez', 'Facultad de Sistemas Biológicos e Innovación Tecnológica (FASBIT), Universidad Autónoma “Benito Juárez” de Oaxaca (UABJO), Oaxaca de Juárez, Oaxaca, México.', 'Unidad Académica de Estudios Territoriales de Oaxaca (UAETO), Instituto de Geografía, Universidad Nacional Autónoma de México (UNAM).', 'La vigilancia genómica ambiental constituye una herramienta esencial para comprender la dinámica y propagación de genes de resistencia a antibióticos (ARGs) en ecosistemas costeros vulnerables. En este estudio se evaluó la diversidad y distribución geográfica del resistoma y los elementos genéticos móviles (MGEs) en comunidades microbianas de cuatro humedales de la costa de Yucatán (El Palmar, Dzilam, Sisal y Progreso), mediante un enfoque metatranscriptómico de alto rendimiento. Se detectaron 3,498 ARGs, principalmente asociados con resistencia a tetraciclinas, macrólidos, rifamicinas, fluoroquinolonas y aminoglucósidos, con mecanismos dominantes de bombas de flujo y modificación de blancos antibióticos. Los resultados evidenciaron un gradiente espacial de abundancia de ARGs y MGEs desde zonas conservadas hasta áreas con mayor influencia antropogénica. Se identificaron cinco clases principales de MGEs (integración/excisión, recombinación/reparación, fagos, transferencia y defensa/estabilidad), predominantes en Proteobacteria y Firmicutes. La correlación positiva entre la abundancia de MGEs y ARGs resalta la importancia de la transferencia horizontal de genes en la expansión de la resistencia antimicrobiana en ambientes costeros tropicales. Este trabajo representa el primer ejercicio de vigilancia genómica costera en la península de Yucatán, y proporciona información clave para el monitoreo ambiental y sanitario, así como para el diseño de estrategias de mitigación que reduzcan la propagación de genes de resistencia en ecosistemas naturales.', 5, 'Aceptado', '2025-10-09 15:42:03', '2025-10-15 02:58:45', 1, 'vigilancia genómica, resistoma ambiental, elementos genéticos móviles, metatranscriptómica, costa de Yucatán, resistencia a antibióticos'),
(137, 259, 'Mario Alberto Martínez Núñez', 'Diversidad y funciones del microbioma del suelo en agroecosistemas y ecosistemas naturales del Geoparque Mixteca Alta, Oaxaca: un enfoque genómico para la sustentabilidad', NULL, 'Unidad Académica de Estudios Territoriales de Oaxaca, Instituto de Geografía, Universidad Nacional Autónoma de México (UNAM).', NULL, 'El presente estudio analiza la diversidad bacteriana y el potencial funcional de los microbiomas del suelo en sistemas agrícolas tradicionales (lama-bordos, terrazas y valles) y ecosistemas naturales (bosques de encino y pino, pastizales y matorrales) del Geoparque Mundial UNESCO Mixteca Alta, Oaxaca. Mediante secuenciación del gen 16S rRNA y análisis bioinformáticos con QIIME2 y PICRUSt2, se identificaron patrones microbianos contrastantes entre los diferentes tipos de suelo. En los agroecosistemas predominaron Acidobacteria, Proteobacteria, Actinobacteria y Chloroflexi, relacionados con el ciclado de nutrientes, la formación de agregados del suelo y la promoción del crecimiento vegetal. En los ecosistemas naturales, las comunidades bacterianas presentaron una mayor diversidad y especialización funcional. Los bosques de encino y pino mostraron abundancias elevadas de Acidobacteriota, Planctomycetota y Verrucomicrobiota, grupos asociados con la degradación de materia orgánica recalcitrante y el reciclaje de nitrógeno y fósforo. Por su parte, los pastizales y matorrales se caracterizaron por la presencia de Actinobacteriota y Gemmatimonadota, vinculados a la resistencia a condiciones áridas y la estabilización del carbono del suelo. Estos resultados evidencian que tanto los sistemas agrícolas tradicionales como los ecosistemas naturales del Geoparque mantienen microbiomas complejos y funcionalmente complementarios, con alto potencial biotecnológico para el manejo sustentable del suelo, la restauración ecológica y la conservación de la biodiversidad microbiana', 5, 'Aceptado', '2025-10-09 15:45:40', '2025-10-15 03:02:21', 1, 'microbioma del suelo, genómica ambiental, agroecosistemas tradicionales, ecosistemas naturales, Oaxaca, sustentabilidad'),
(138, 132, 'L. González-Reyes', 'Sensor de temperatura de fibra óptica en un interferómetro de Michelson', 'J. L. Cano-Pérez, C. PérezCampos-Mayoral, P. Batres-Mendoza, E. I. Guerra-Hernández, M. Vargas-Treviño, A. Martínez-Helmes y J. Gutiérrez- Gutiérrez', 'Facultad de Sistemas Biológicos e Innovación tecnológica, Universidad Autónoma “Benito Juárez” de Oaxaca (FASBIT-UABJO), Av. Universidad S/N, Ex-Hacienda 5 Señores, C.P. 68120, Oaxaca de Juárez, México', 'Facultad de Contaduría y Administración, Universidad Autónoma “Benito Juárez” de Oaxaca (FCA-UABJO), Av. Universidad S/N, Ex-Hacienda 5 Señores, C.P. 68120, Oaxaca de Juárez, México.', 'En la última década, el sensor de temperatura de fibra óptica se ha desarrollado rápidamente, debido a sus ventajas únicas como alta sensibilidad, tamaño pequeño, peso ligero e inmunidad a la interferencia electromagnética. Los interferómetros con diferentes estructuras en fibras ópticas se han construido para lograr una máxima sensibilidad, entre ellos, el interferómetro de Mach Zehnder, el interferómetro de Fabry Perot (FPI) y el interferómetro de Michelson (MI). En este trabajo es reportado la fabricación de un MI-Taper y así como su caracterización de su respuesta con incrementos de temperatura. Su estructura es de fibra óptica monomodo, y se fabricó con una empalmadora (Fitel S179) mediante descargas eléctricas controladas. Se caracterizaron dos configuraciones de manera experimental, el primer MI con una longitud L= 3.5 cm, se obtuvo una sensibilidad de 15.2 pm/°C con un coeficiente de correlación R² = 0.99126 en el rango de 25–218 °C. El segundo MI con una longitud L= 4.0 cm, mostró una sensibilidad de 328.8 pm/°C con R² = 0.98912 en el rango de 25.8–47 °C. Estos resultados confirman el potencial de los interferómetros Michelson en fibra óptica para el desarrollo de sensores de temperatura altamente sensibles en distintos intervalos operativos.', 1, 'Aceptado', '2025-10-11 19:59:31', '2025-10-13 03:06:12', 1, NULL),
(144, 319, 'CARLOS ALBERTO MATIAS CERVANTES', 'Análisis in silico de la secuencia proteica de la vacuna abdalá como posible generadora de peptidos antimicrobianos', NULL, 'FACULTAD DE MEDICINA Y CIRUGÍA, UABJO', NULL, 'Contenido del resumen pendiente de carga.', 5, 'Aceptado', '2025-11-27 14:52:11', '2025-11-27 14:55:16', 1, NULL),
(145, 318, 'EDWIN RENE', 'Desempeño de concretos con sustitución parcial de vidrio expuestos en el puerto de Telchac, Yucatán', NULL, 'SECIHTI-CINVESTAV MÉRIDA', NULL, 'En México, los residuos sólidos urbanos representan un problema directamente relacionado con el crecimiento demográfico. En el caso de Yucatán, la población se incrementó de 1,955,577 habitantes en 2010 a 2,320,898 en 2020, mientras que la generación de residuos fue de 2,475 toneladas diarias, compuestas principalmente por orgánicos, cartón, plásticos y vidrio, entre otros materiales. En el caso del vidrio, al ser un material no biodegradable, ocupa grandes volúmenes en los rellenos sanitarios, genera criaderos de vectores y puede provocar incendios durante la temporada de estío. Sin embargo, este material puede ser revalorizado al incorporarse parcialmente como material cementicio en pastas, morteros y concretos. Este trabajo presenta los resultados de desempeño de muestras de concreto con relaciones a/c = 0.40 y 0.70, con 0% y 15% de vidrio, expuestas en un ambiente marino.', 2, 'Aceptado', '2025-12-11 02:30:04', '2025-12-11 02:31:46', 1, 'desechos de vidrio, revalorización, material cementicio'),
(149, 155, 'RIta Aide Robles Castillejos', 'Reconocimiento de patrones de agarre mediante  imaginación motora y señales EEG para el control de  prótesis de mano', 'E. I. Guerra-Hernández1\nA. Espinal2\nJ. Gutiérrez-Gutiérrez1\nJ. G. Beltrán-Hernández1\nM. A. Sánchez-Medina1\nP. Batres-Mendoza1', 'Facultad de Sistemas Biológicos e Innovación tecnológica, Universidad Autónoma “Benito Juárez” de Oaxaca (FASBIT-UABJO), Av. Universidad S/N, Ex-Hacienda 5 Señores, C.P. 68120, Oaxaca de Juárez, México', 'Departamento de Estudios Organizacionales-DCEA, Universidad de Guanajuato, Guanajuato, Gto., México.', 'Las interfaces cerebro-computadora (BCI) han avanzado notablemente, especialmente en aplicaciones de rehabilitación y asistencia para personas con discapacidades motoras. La clasificación de agarres a partir de señales de EEG durante la imaginación motora es crucial para desarrollar sistemas de control de prótesis de mano. Estos sistemas no invasivos permiten un control más preciso y personalizado, lo que mejora la calidad de vida de los usuarios. Este trabajo tiene como objetivo diseñar y evaluar un modelo de clasificación capaz de distinguir entre cinco estados de imaginación motora entre estado de reposo y cuatro tipos de agarre de la mano derecha: esférico, cilíndrico, de gancho y de pinza. Para este propósito, se utilizó una red neuronal de tipo LSTM. El estudio incluyó a 14 participantes, de quienes se adquirieron las señales de EEG mediante una interfaz cerebro-computadora equipada con 14 electrodos. Para optimizar el rendimiento del modelo, el conjunto de datos se dividió en proporciones del 70% para entrenamiento, 15% para validación y 15% para prueba, asegurando una distribución equilibrada de las clases. Los resultados obtenidos en la fase de validación alcanzaron una precisión del 92.57 %, demostrando la eficacia del modelo LSTM para identificar patrones complejos de actividad cerebral asociados a distintos tipos de agarre.', 4, 'Aceptado', '2025-12-22 03:09:59', '2025-12-22 03:24:23', 1, 'Señales cerebrales EEG,BCI,Redes Neuronales LSTM,Patrones de agarre,Imaginación Motora'),
(155, 401, 'test autor', 'test', 'test', 'test', 'test', 'test', 4, 'Aceptado', '2026-02-10 19:34:47', '2026-02-10 19:35:57', 1, 'test'),
