(150, 145, 58, 'Aceptado', '', '2025-12-11 02:31:15', '2025-12-11 02:31:46'),
(154, 149, 60, 'Aceptado', 'Resumen Aceptado.', '2025-12-22 03:23:38', '2025-12-22 03:24:23'),
