(378, 'Dra. ', 'Centro de Investigación Científica y de Educación Superior de Ensenada, Unidad Académica Monterrey', 'Investigadora Asociada', 'óptica física, nano-óptica, plasmónica', '0000-0002-5449-0688', 'https://scholar.google.com/citations?user=MoxYhDYAAAAJ&hl=es', 'sni_378_1768419191.pdf', NULL, 1),
(379, 'Dra.', 'Universidad Autónoma Benito Juárez de Oaxaca', 'Profesor Investigador', 'Patología Clínica y Diagnóstico Biomédico, con énfasis en el estudio de enfermedades metabólicas como la obesidad y la diabetes mellitus, el análisis de la actividad plaquetaria y su relación con procesos inflamatorios y trombóticos, así como la evaluación clínica y biomédica de COVID-19 y otras enfermedades emergentes, orientadas a mejorar la detección, el seguimiento y la comprensión integral de su impacto en la salud.', '0000-0003-4140-4661', 'https://scholar.google.com/citations?hl=es&user=AOMl3ngAAAAJ', 'sni_379_1768399128.pdf', 'foto_379_1768399128.jpeg', 1),
(380, 'Dra. ', 'Secretaría de Ciencia, Humanidades, Tecnología e Innovación (SECIHTI)', 'Investigadora por México ', 'Estudio de las bases moleculares y celulares de las enfermedades crónico-degenerativas, con énfasis en los procesos fisiopatológicos que contribuyen a su inicio y progresión.\r\nInvestigación de los mecanismos celulares y moleculares del cáncer, incluyendo alteraciones en la proliferación, apoptosis, senescencia y respuesta al estrés.\r\nAnálisis integral del envejecimiento, enfocado en los cambios celulares, metabólicos y funcionales asociados a la pérdida de la homeostasis.\r\nExploración de mecanismos celulares implicados en el envejecimiento y en patologías asociadas, tales como daño oxidativo, inflamación crónica y disfunción mitocondrial.\r\nInvestigación de la hemostasia, abordando los procesos de coagulación, función plaquetaria y su relación con el envejecimiento, el cáncer y las enfermedades crónico-degenerativas.\r\nEvaluación del uso de productos naturales y compuestos bioactivos como estrategias para promover un envejecimiento exitoso y mejorar la calidad de vida en etapas avanzadas.', 'https://orcid.org/0000-0003-2182-2540', 'https://scholar.google.com/citations?user=Iux3Wf4AAAAJ&hl=es&oi=ao', 'sni_380_1768332979.pdf', 'foto_380_1768332979.png', 1),
(383, 'Dr.', 'Instituto de Fisiología Celular, UNAM', 'Técnico Académico Titular B', 'Modelos animales (ratones transgénicos) utilizados en diversos condiciones experimentales aplicados al entendimiento del funcionamiento del sistema nervioso central.\r\nTécnicas de biología molecular y celular aplicadas al estudio y entendimiento de diferentes tipos de cáncer.\r\nOptogenética, Neurofisiología.', '0000-0001-7574-8724', '55053316900', 'sni_383_1768432870.pdf', NULL, 1),
