(108, 77, 386, '{\"pregunta_1\": \"si\", \"pregunta_2\": \"si\", \"pregunta_3\": \"si\", \"pregunta_4\": \"si\", \"pregunta_5\": \"si\", \"pregunta_6\": \"si\"}', 'Gran trabajo, muchas felicidades', 'Favorable y Publicable', NULL, 'evaluacion_108_firmada_1772929376.pdf', 'Validada', NULL, '2026-02-11 19:22:33', '2026-03-08 00:23:16'),
